export const ba_fused_super_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// Fused super-kernel for the bin-packed pair-tree MSM bucket-accumulate.
//
// Combines marshal + disjoint + scatter into one kernel. Each thread t
// handles one pair_block of S pairs (a "pair_block" = the unit of fused
// affine-add work the level loop batches through a shared inversion):
//   1. Read 2*S source indices from pair_block_plan (idx_l, idx_r per slot).
//   2. Read S destination indices from scatter_plan.
//   3. Load S pair-x values from active_sums_old, compute S dx values
//      and forward prefix product.
//   4. Single field inversion on the prefix product.
//   5. Inverse pass: per slot k from S-1 down to 0, derive
//      inv_dx[k] = 1/dx_k from the running inverse and write it back to
//      pref_scratch. The running inverse is loop-carried only here.
//   6. Backward peel: per slot k, read inv_dx[k]:
//        - load .x and .y for both operands
//        - lean affine add -> R_x, R_y
//        - write directly to active_sums_new at scatter_plan[t*S + k]
//
// Field elements are 8x u32 throughout (Lever 2); see field8_funcs.
//
// PARAMS:
//   params.x = total_pair_blocks  (active threads, one per pair_block)
//   params.y = M_old              (active_sums_old vec4-stride length)
//   params.z = M_new              (active_sums_new vec4-stride length)
//
// Layout (both active_sums buffers): 2 planes (P.x, P.y), PG=2 vec4 per
// element. plane_p flat vec4 base = p * PG * M, element e at offset
// PG * e.

const S: u32 = {{ s }}u;
const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       pair_block_plan:      array<u32>;
@group(0) @binding(1) var<storage, read>       scatter_plan:    array<u32>;
{{#l0_index_mode}}
// Lever B: at level 0 active_sums_old is a flat (point index | sign<<31)
// array; the operand points are gathered from the pool (point_x/point_y).
@group(0) @binding(2) var<storage, read>       active_sums_old: array<u32>;
{{/l0_index_mode}}
{{^l0_index_mode}}
@group(0) @binding(2) var<storage, read>       active_sums_old: array<vec4<u32>>;
{{/l0_index_mode}}
@group(0) @binding(3) var<storage, read_write> active_sums_new: array<vec4<u32>>;
@group(0) @binding(4) var<uniform>             params:          vec4<u32>;
@group(0) @binding(5) var<storage, read_write> pref_scratch:    array<vec4<u32>>;
{{#l0_index_mode}}
@group(0) @binding(6) var<storage, read>       point_x:         array<vec4<u32>>;
@group(0) @binding(7) var<storage, read>       point_y:         array<vec4<u32>>;
{{/l0_index_mode}}

{{#l0_index_mode}}
const L0_SIGN_BIT: u32 = 0x80000000u;
const L0_IDX_MASK: u32 = 0x7fffffffu;

// Level-0 operand load: active_sums_old[idx] is (point index | sign<<31);
// gather the coordinate from the pool. \`M\` is unused here.
fn load_active_x(idx: u32, M: u32) -> array<u32, 8> {
    let pt = active_sums_old[idx] & L0_IDX_MASK;
    let q0 = point_x[2u * pt];
    let q1 = point_x[2u * pt + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn load_active_y(idx: u32, M: u32) -> array<u32, 8> {
    let packed = active_sums_old[idx];
    let pt = packed & L0_IDX_MASK;
    let q0 = point_y[2u * pt];
    let q1 = point_y[2u * pt + 1u];
    let y: array<u32, 8> = array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
    if ((packed & L0_SIGN_BIT) == 0u) {
        return y;
    }
    // Lever D: negate y on the fly (-y = 0 - y mod p) — the level-0 point
    // pool carries no precomputed -y plane.
    let zero: array<u32, 8> = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
    return fr_sub_f8(zero, y);
}
{{/l0_index_mode}}
{{^l0_index_mode}}
fn load_active_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = 0u * PG * M + PG * idx;
    let q0 = active_sums_old[base + 0u];
    let q1 = active_sums_old[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn load_active_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = 1u * PG * M + PG * idx;
    let q0 = active_sums_old[base + 0u];
    let q1 = active_sums_old[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}
{{/l0_index_mode}}

fn store_active_new(plane: u32, idx: u32, M: u32, val: array<u32, 8>) {
    let base = plane * PG * M + PG * idx;
    active_sums_new[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    active_sums_new[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

// pref_scratch holds the forward prefix products (then the per-slot
// inverses), 8x u32 = two vec4 per entry. Thread-major — global slot =
// t*S + k — so each thread's S entries are contiguous and stay
// cache-resident across the forward/backward gap.
fn store_pref(slot: u32, val: array<u32, 8>) {
    let base = 2u * slot;
    pref_scratch[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    pref_scratch[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn load_pref(slot: u32) -> array<u32, 8> {
    let base = 2u * slot;
    let q0 = pref_scratch[base + 0u];
    let q1 = pref_scratch[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let T = params.x;
    let M_old = params.y;
    let M_new = params.z;
    let t = gid.x{{#tiled}} + params.w{{/tiled}};
    if (t >= T) { return; }

    // pref_scratch index. Lever A (tiled) sizes pref_scratch to a single
    // tile of T_TILE threads, so it is indexed by the tile-local thread id
    // (gid.x); params.w carries the tile's global base. Untiled callers
    // pass params.w = 0 and pref_scratch spans all T threads.
{{#tiled}}
    let pref_base = gid.x * S;
{{/tiled}}
{{^tiled}}
    let pref_base = t * S;
{{/tiled}}

    let block_base = 2u * S * t;

    // Forward: compute S dx values and accumulate the prefix product.
    var acc: array<u32, 8> = get_r_f8();
    for (var k: u32 = 0u; k < S; k = k + 1u) {
        let idx_l = pair_block_plan[block_base + 2u * k + 0u];
        let idx_r = pair_block_plan[block_base + 2u * k + 1u];
        let p_lx: array<u32, 8> = load_active_x(idx_l, M_old);
        let p_rx: array<u32, 8> = load_active_x(idx_r, M_old);
        let dx: array<u32, 8> = fr_sub_f8(p_rx, p_lx);
        if (k == 0u) {
            acc = dx;
        } else {
            acc = montgomery_product_f8(acc, dx);
        }
        store_pref(pref_base + k, acc);
    }

    // Single inversion per pair_block. The safegcd inverse is 20x13-limb; the
    // accumulate is 8x u32, so expand on the way in and contract the
    // result — one conversion pair per pair_block.
    var acc20: BigInt = unpack256_to_limbs(acc);
    var inv20: BigInt = {{ inv_fn }}(acc20);
    var inv: array<u32, 8> = pack_limbs_to_256(&inv20);

    // Inverse pass: walk k descending, derive inv_dx[k] = 1/dx_k from the
    // running inverse + the stored forward prefix products, and write it
    // back into pref_scratch slot k. The running \`inv\` is loop-carried
    // only in this multiply-only loop, so it is NOT live across the
    // affine-add peel below. store_pref(k) is safe: a later (smaller-k)
    // iteration only reads slots < k, an earlier one only wrote slots > k.
    for (var jj: u32 = 0u; jj < S; jj = jj + 1u) {
        let k = S - 1u - jj;
        var inv_dx: array<u32, 8>;
        if (k == 0u) {
            inv_dx = inv;
        } else {
            let pp: array<u32, 8> = load_pref(pref_base + (k - 1u));
            inv_dx = montgomery_product_f8(inv, pp);
            // Advance the running inverse by dx_k for the next iteration;
            // dx_k is recomputed from the slot's x-coordinates.
            let idx_l = pair_block_plan[block_base + 2u * k + 0u];
            let idx_r = pair_block_plan[block_base + 2u * k + 1u];
            let p_lx: array<u32, 8> = load_active_x(idx_l, M_old);
            let p_rx: array<u32, 8> = load_active_x(idx_r, M_old);
            let dx_back: array<u32, 8> = fr_sub_f8(p_rx, p_lx);
            inv = montgomery_product_f8(inv, dx_back);
        }
        store_pref(pref_base + k, inv_dx);
    }

    // Backward peel: emit S pair sums, scatter to active_sums_new. Reads
    // the per-slot inverse inv_dx[k] from pref_scratch — no running
    // inverse is live across the affine add. Each coordinate is loaded
    // just before first use to minimise the simultaneously-live set.
    for (var jj: u32 = 0u; jj < S; jj = jj + 1u) {
        let k = S - 1u - jj;
        let idx_l = pair_block_plan[block_base + 2u * k + 0u];
        let idx_r = pair_block_plan[block_base + 2u * k + 1u];

        let inv_dx: array<u32, 8> = load_pref(pref_base + k);

        // lambda = (p_ry - p_ly) / dx_k.
        let p_ly: array<u32, 8> = load_active_y(idx_l, M_old);
        let p_ry: array<u32, 8> = load_active_y(idx_r, M_old);
        var lambda: array<u32, 8> = fr_sub_f8(p_ry, p_ly);
        lambda = montgomery_product_f8(lambda, inv_dx);

        // r_x = lambda^2 - p_lx - p_rx.
        let p_lx: array<u32, 8> = load_active_x(idx_l, M_old);
        let p_rx: array<u32, 8> = load_active_x(idx_r, M_old);
        var r_x: array<u32, 8> = montgomery_product_f8(lambda, lambda);
        let x_sum: array<u32, 8> = fr_add_f8(p_lx, p_rx);
        r_x = fr_sub_f8(r_x, x_sum);

        // r_y = lambda * (p_lx - r_x) - p_ly.
        var r_y: array<u32, 8> = fr_sub_f8(p_lx, r_x);
        r_y = montgomery_product_f8(lambda, r_y);
        r_y = fr_sub_f8(r_y, p_ly);

        let dst_idx = scatter_plan[t * S + k];
        store_active_new(0u, dst_idx, M_new, r_x);
        store_active_new(1u, dst_idx, M_new, r_y);
    }

    {{{ recompile }}}
}
`;

export const ba_planner_v2_emit = `// MSM bucket-accumulate planner — pass B of 2: parallel plan emit.
//
// Dispatch (ceil(BW/TPB), NUM_WINDOWS): one workgroup per (bucket-group,
// window), one thread per bucket. Reads the per-bucket offsets pass A
// (ba_planner_v2_offsets) computed and emits the pair-block / scatter /
// carry plan entries — the O(pairs) work, now spread across NUM_GROUPS *
// NUM_WINDOWS workgroups instead of one workgroup per window.
//
// "pair_block": the unit of fused-affine-add work. The pair-tree level loop
// pulls pairs S at a time (one block) and feeds them through a shared
// batched inversion. Each window's pairs are packed into
// \`pair_blocks_per_window\` blocks of S pairs each; \`pair_block_plan\` holds
// 2*S u32 per block (S left-indices + S right-indices).
//
// The window-local pair prefix is derived as
//   new_offsets[b] - w*wstride - carry_off[b].
// After emitting, the window's NUM_GROUPS workgroups cooperatively pad
// the plan tail (lever-E self-pad) with the pad trio. The emit writes
// plan slots [0, total_pairs) and the pad writes [total_pairs, block
// slots) — disjoint ranges, so no ordering between them is needed.

const TPB: u32 = {{ workgroup_size }}u;
const BW: u32 = {{ buckets_per_window }}u;
const NUM_WINDOWS: u32 = {{ num_windows }}u;
const NUM_GROUPS: u32 = {{ num_groups }}u;
const PAIR_CAP: u32 = {{ pair_cap }}u;
const S: u32 = {{ s }}u;

@group(0) @binding(0) var<storage, read>       counts:       array<u32>;
@group(0) @binding(1) var<storage, read>       offsets:      array<u32>;
@group(0) @binding(2) var<storage, read>       carry_off:    array<u32>;
@group(0) @binding(3) var<storage, read>       new_offsets:  array<u32>;
@group(0) @binding(4) var<storage, read>       plan_meta:    array<u32>;
@group(0) @binding(5) var<storage, read_write> pair_block_plan: array<u32>;
@group(0) @binding(6) var<storage, read_write> scatter_plan:    array<u32>;
@group(0) @binding(7) var<storage, read_write> carry_plan:      array<u32>;
@group(0) @binding(8) var<uniform>             params:          vec4<u32>;
@group(0) @binding(9) var<uniform>             pad_params:      vec4<u32>;

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let bg = wid.x;
    let w = wid.y;
    if (w >= NUM_WINDOWS) { return; }

    let pair_blocks_per_window = params.x;
    let carries_per_window     = params.y;
    let wstride                = params.w;
    let window_block_base      = w * pair_blocks_per_window;
    let window_carry_base      = w * carries_per_window;

    // Emit this bucket's pair / carry plan entries.
    let b_local = bg * TPB + tid;
    if (b_local < BW) {
        let b = w * BW + b_local;
        let n = counts[b];
        let pc = n / 2u;
        let cf = select(n & 1u, 0u, n == 1u);
        let bucket_base = offsets[b];
        let no = new_offsets[b];
        let co = carry_off[b];
        let po = (no - w * wstride) - co;   // window-local pair prefix

        for (var j: u32 = 0u; j < PAIR_CAP; j = j + 1u) {
            if (j >= pc) { break; }
            let slot_in_window = po + j;
            let global_block  = window_block_base + slot_in_window / S;
            let slot_in_block = slot_in_window % S;
            let flat_slot     = global_block * S + slot_in_block;
            pair_block_plan[2u * flat_slot + 0u] = bucket_base + 2u * j;
            pair_block_plan[2u * flat_slot + 1u] = bucket_base + 2u * j + 1u;
            scatter_plan[flat_slot] = no + j;
        }
        if (cf != 0u) {
            let cs = window_carry_base + co;
            carry_plan[2u * cs + 0u] = bucket_base + n - 1u;
            carry_plan[2u * cs + 1u] = no + pc;
        }
    }

    // Lever-E self-pad: the window's NUM_GROUPS workgroups cooperatively
    // fill the plan tail past the real entries with the pad trio.
    let pad_l = pad_params.x;
    let pad_r = pad_params.y;
    let pad_d = pad_params.z;
    let total_pairs   = plan_meta[3u * w + 0u];
    let total_carries = plan_meta[3u * w + 1u];
    let block_slots   = pair_blocks_per_window * S;
    let stripe = bg * TPB + tid;
    let pad_stride = NUM_GROUPS * TPB;
    for (var sp: u32 = total_pairs + stripe; sp < block_slots; sp = sp + pad_stride) {
        let flat = window_block_base * S + sp;
        pair_block_plan[2u * flat + 0u] = pad_l;
        pair_block_plan[2u * flat + 1u] = pad_r;
        scatter_plan[flat] = pad_d;
    }
    for (var sc: u32 = total_carries + stripe; sc < carries_per_window; sc = sc + pad_stride) {
        let cflat = window_carry_base + sc;
        carry_plan[2u * cflat + 0u] = pad_l;
        carry_plan[2u * cflat + 1u] = pad_d;
    }

    {{{ recompile }}}
}
`;

export const ba_planner_v2_offsets = `// MSM bucket-accumulate planner — pass A of 2: per-window scan + offsets.
//
// One workgroup per Pippenger window. Computes, for every bucket, the
// window-local prefix offsets the emit pass (ba_planner_v2_emit) needs,
// plus new_counts / new_offsets and the per-window plan_meta totals — but
// NOT the O(pairs) pair_block / scatter / carry plans, which the emit
// pass writes in parallel across buckets.
//
// Phase A  per-thread tally of (pair, carry, new) counts.
// Phase B  workgroup Hillis-Steele scan of the 3 per-thread totals.
// Phase C  per bucket: write new_counts, new_offsets, carry_off. The emit
//          pass derives the pair prefix as new_offsets - w*wstride
//          - carry_off (pc + cf = nc, so the pair prefix is the new
//          prefix minus the carry prefix).
// Phase D  window totals + level-wide indirect-dispatch args.
//
// O(BW) per window — flat in n, so the NUM_WINDOWS-workgroup dispatch is
// not an occupancy bottleneck (the O(pairs) work is all in the emit pass).

const TPB: u32 = {{ workgroup_size }}u;
const BW: u32 = {{ buckets_per_window }}u;
const PER_THREAD: u32 = {{ per_thread }}u;
const NUM_WINDOWS: u32 = {{ num_windows }}u;

@group(0) @binding(0) var<storage, read>       counts:      array<u32>;
@group(0) @binding(1) var<storage, read_write> carry_off:   array<u32>;
@group(0) @binding(2) var<storage, read_write> new_counts:  array<u32>;
@group(0) @binding(3) var<storage, read_write> new_offsets: array<u32>;
@group(0) @binding(4) var<storage, read_write> plan_meta:   array<u32>;
@group(0) @binding(5) var<uniform>             params:      vec4<u32>;

var<workgroup> pair_scan:  array<u32, {{ workgroup_size }}>;
var<workgroup> carry_scan: array<u32, {{ workgroup_size }}>;
var<workgroup> new_scan:   array<u32, {{ workgroup_size }}>;

fn ceil_div(a: u32, b: u32) -> u32 {
    return (a + b - 1u) / b;
}

@compute @workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let w = wid.x;
    if (w >= NUM_WINDOWS) { return; }

    let pair_blocks_per_window = params.x;
    let carries_per_window     = params.y;
    let wstride                = params.w;
    let window_bucket_base = w * BW;

    // Phase A: per-thread tally over this thread's PER_THREAD buckets.
    var sum_p: u32 = 0u;
    var sum_c: u32 = 0u;
    var sum_n: u32 = 0u;
    for (var k: u32 = 0u; k < PER_THREAD; k = k + 1u) {
        let b_local = tid * PER_THREAD + k;
        if (b_local < BW) {
            let n = counts[window_bucket_base + b_local];
            let pc = n / 2u;
            let cf = select(n & 1u, 0u, n == 1u);
            sum_p += pc;
            sum_c += cf;
            sum_n += pc + cf;
        }
    }

    // Phase B: workgroup Hillis-Steele inclusive scan (3 interleaved).
    pair_scan[tid] = sum_p;
    carry_scan[tid] = sum_c;
    new_scan[tid] = sum_n;
    workgroupBarrier();
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var add_p: u32 = 0u;
        var add_c: u32 = 0u;
        var add_n: u32 = 0u;
        if (tid >= stride) {
            add_p = pair_scan[tid - stride];
            add_c = carry_scan[tid - stride];
            add_n = new_scan[tid - stride];
        }
        workgroupBarrier();
        if (tid >= stride) {
            pair_scan[tid] = pair_scan[tid] + add_p;
            carry_scan[tid] = carry_scan[tid] + add_c;
            new_scan[tid] = new_scan[tid] + add_n;
        }
        workgroupBarrier();
    }
    var local_carry_off: u32 = carry_scan[tid] - sum_c;
    var local_new_off: u32 = new_scan[tid] - sum_n;

    // Phase D: window totals + level-wide indirect-dispatch args.
    if (tid == TPB - 1u) {
        plan_meta[3u * w + 0u] = pair_scan[tid];
        plan_meta[3u * w + 1u] = carry_scan[tid];
        plan_meta[3u * w + 2u] = new_scan[tid];
    }
    if (w == 0u && tid == 0u) {
        let wgi = max(params.z, 1u);
        let d = 3u * NUM_WINDOWS;
        plan_meta[d + 0u] = ceil_div(NUM_WINDOWS * pair_blocks_per_window, wgi);
        plan_meta[d + 1u] = 1u;
        plan_meta[d + 2u] = 1u;
        plan_meta[d + 3u] = ceil_div(NUM_WINDOWS * carries_per_window, wgi);
        plan_meta[d + 4u] = 1u;
        plan_meta[d + 5u] = 1u;
    }

    // Phase C: per-bucket offsets — consumed by the emit pass.
    for (var k: u32 = 0u; k < PER_THREAD; k = k + 1u) {
        let b_local = tid * PER_THREAD + k;
        if (b_local >= BW) { break; }
        let b = window_bucket_base + b_local;
        let n = counts[b];
        let pc = n / 2u;
        let cf = select(n & 1u, 0u, n == 1u);
        new_counts[b] = pc + cf;
        new_offsets[b] = w * wstride + local_new_off;
        carry_off[b] = local_carry_off;
        local_carry_off += cf;
        local_new_off += pc + cf;
    }

    {{{ recompile }}}
}
`;

export const ba_reduce_init_bench = `// Reduction-stage init: repack the bucket-accumulate output into the
// reduction's working buffer, and seed the present-mask.
//
// bucket_result has BW columns per window; the weighted buckets are the
// digit magnitudes 1..2^(c-1) — column 0 is the zero digit (weight 0) and
// is dropped, columns past 2^(c-1) are padding and are dropped. red_buf is
// laid out with STRIDE = 2^(c-1) columns per window (a power of two — what
// the 4-phase reduction requires). One thread per red_buf element: copy
// the matching bucket_result element and set is_present iff it is
// non-zero (an empty bucket's accumulate output stays all-zero).

const PG: u32 = 2u;

@group(0) @binding(0) var<storage, read>       bucket_result: array<vec4<u32>>;
@group(0) @binding(1) var<storage, read_write> red_buf:       array<vec4<u32>>;
@group(0) @binding(2) var<storage, read_write> is_present:    array<u32>;
@group(0) @binding(3) var<uniform>             params:        vec4<u32>;
// params.x = total   (NUM_WINDOWS * STRIDE — red_buf element count)
// params.y = STRIDE  (red_buf columns per window)
// params.z = BW      (bucket_result columns per window)
// params.w = B_TOTAL (bucket_result element stride = NUM_WINDOWS * BW)

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let g = gid.x;
    let total = params.x;
    if (g >= total) {
        return;
    }
    let stride = params.y;
    let bw = params.z;
    let b_total = params.w;

    let w = g / stride;
    let i = g % stride;
    // red_buf slot i  <-  bucket_result weighted column (i + 1).
    let src = w * bw + i + 1u;

    let src_x = PG * src;
    let src_y = PG * b_total + PG * src;
    let dst_x = PG * g;
    let dst_y = PG * total + PG * g;

    let x0 = bucket_result[src_x + 0u];
    let x1 = bucket_result[src_x + 1u];
    let y0 = bucket_result[src_y + 0u];
    let y1 = bucket_result[src_y + 1u];

    red_buf[dst_x + 0u] = x0;
    red_buf[dst_x + 1u] = x1;
    red_buf[dst_y + 0u] = y0;
    red_buf[dst_y + 1u] = y1;

    let nz = x0.x | x0.y | x0.z | x0.w | x1.x | x1.y | x1.z | x1.w
           | y0.x | y0.y | y0.z | y0.w | y1.x | y1.y | y1.z | y1.w;
    is_present[g] = select(0u, 1u, nz != 0u);

    {{{ recompile }}}
}
`;

export const ba_reduce_level_bench = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}
{{> bigint_by_funcs }}
{{> inverse_funcs }}

{{{ dec_unpack }}}

{{{ dec_pack }}}

{{> field8_funcs }}

// One level of the recursive affine bucket reduction. The host issues one
// dispatch per schedule level; WebGPU's between-pass ordering provides the
// cross-level memory ordering. The kind (phase-A suffix add, phase-B/D tree-add,
// phase-C double) is selected at template-generation time, so each of the
// three compiled variants is straight-line code for exactly one phase.
//
// Branchless: every data-dependent decision (bucket presence, the
// add-vs-copy-vs-skip cases, the per-candidate denominator) is a \`select\`,
// not an \`if\`. Point-equality (P = +/-Q) handling is omitted — the algorithm
// assumes uniformly-random inputs with no point collisions, so the affine
// add denominator x_s - x_d is never zero. Removing those branches keeps a
// single straight-line path live, which the Adreno register allocator can
// schedule without spilling. The only surviving \`if\` is the workgroup-tail
// store guard: tail lanes (j2 >= ppw) have out-of-window targets, so their
// red_buf / is_present writes must be suppressed to avoid corrupting
// neighbouring windows.
//
// One workgroup per window. Field elements are 8x u32 (Lever 2); see
// field8_funcs.

const PG: u32 = 2u;
const WG: u32 = {{ workgroup_size }}u;

@group(0) @binding(0) var<storage, read_write> red_buf:      array<vec4<u32>>;
@group(0) @binding(1) var<storage, read_write> is_present:   array<u32>;
@group(0) @binding(2) var<storage, read_write> pref_scratch: array<vec4<u32>>;
@group(0) @binding(3) var<uniform>             cparams:      vec4<u32>;
@group(0) @binding(4) var<uniform>             lparams:      vec4<u32>;
// cparams = (M (red_buf element stride), maxc (pref slots/thread), STRIDE, _)
//   — constant across all levels.
// lparams = (pa, pb, ppw, _) — this level's flattened schedule entry.

fn load_x(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn load_y(idx: u32, M: u32) -> array<u32, 8> {
    let base = PG * M + PG * idx;
    let q0 = red_buf[base + 0u];
    let q1 = red_buf[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

fn store_x(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn store_y(idx: u32, M: u32, val: array<u32, 8>) {
    let base = PG * M + PG * idx;
    red_buf[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    red_buf[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn store_pref(slot: u32, val: array<u32, 8>) {
    let base = 2u * slot;
    pref_scratch[base + 0u] = vec4<u32>(val[0], val[1], val[2], val[3]);
    pref_scratch[base + 1u] = vec4<u32>(val[4], val[5], val[6], val[7]);
}

fn load_pref(slot: u32) -> array<u32, 8> {
    let base = 2u * slot;
    let q0 = pref_scratch[base + 0u];
    let q1 = pref_scratch[base + 1u];
    return array<u32, 8>(q0.x, q0.y, q0.z, q0.w, q1.x, q1.y, q1.z, q1.w);
}

// Branchless elementwise select on the 8x u32 field form: returns \`b\` when
// \`cond\`, else \`a\` (matches WGSL's select(false_val, true_val, cond)).
fn fr_select_f8(a: array<u32, 8>, b: array<u32, 8>, cond: bool) -> array<u32, 8> {
    return array<u32, 8>(
        select(a[0], b[0], cond), select(a[1], b[1], cond),
        select(a[2], b[2], cond), select(a[3], b[3], cond),
        select(a[4], b[4], cond), select(a[5], b[5], cond),
        select(a[6], b[6], cond), select(a[7], b[7], cond));
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(workgroup_id) wgid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
    let w = wgid.x;       // window — one workgroup per window
    let tid = lid.x;      // thread within the workgroup
    let M = cparams.x;
    let maxc = cparams.y;
    let stride = cparams.z;
    let pa = lparams.x;
    let pb = lparams.y;
    let ppw = lparams.z;
    let base = w * stride;
    let scratch_base = (w * WG + tid) * maxc;
    // Candidates per thread this level — uniform across the workgroup.
    let C = (ppw + WG - 1u) / WG;

    // Lanes whose entire candidate range is past ppw do no useful work (no
    // red_buf / is_present writes; pref_scratch is private per thread). Return
    // before the safegcd inversion so they issue no instructions and, on a
    // register-starved GPU, generate no register-spill traffic. This is a
    // workgroup-uniform whole-lane skip, distinct from the per-candidate
    // divergent branches removed throughout the rest of the kernel.
    if (tid * C >= ppw) {
        return;
    }
    let R: array<u32, 8> = get_r_f8();

    // ---- forward: prefix product of per-candidate denominators ----
    // Absent / out-of-range candidates contribute the identity R, so the
    // product (and its single inverse) is unaffected.
    var acc: array<u32, 8> = R;
    for (var k: u32 = 0u; k < C; k = k + 1u) {
        let j2 = tid * C + k;
        let in_range = j2 < ppw;
{{#kind2}}
        let slot = base + (j2 + 1u) * pa;
        let present = in_range && (is_present[slot] != 0u);
        let yv: array<u32, 8> = load_y(slot, M);
        let real_denom: array<u32, 8> = fr_add_f8(yv, yv); // 2y
{{/kind2}}
{{^kind2}}
{{#kind0}}
        let src = base + j2 * pa + pb;
        let dst = base + j2 * pa + pb - 1u;
{{/kind0}}
{{#kind1}}
        let dst = base + 2u * j2 * pa;
        let src = base + (2u * j2 + 1u) * pa;
{{/kind1}}
        let present = in_range && (is_present[src] != 0u) && (is_present[dst] != 0u);
        let x_s: array<u32, 8> = load_x(src, M);
        let x_d: array<u32, 8> = load_x(dst, M);
        let real_denom: array<u32, 8> = fr_sub_f8(x_s, x_d); // x_s - x_d (nonzero: no collisions)
{{/kind2}}
        let denom: array<u32, 8> = fr_select_f8(R, real_denom, present);
        acc = montgomery_product_f8(acc, denom);
        store_pref(scratch_base + k, acc);
    }

    // Single inversion per chunk. The safegcd inverse is 20x13-limb; the
    // reduction is 8x u32, so expand on the way in and contract the result.
    var acc20: BigInt = unpack256_to_limbs(acc);
    var inv20: BigInt = {{ inv_fn }}(acc20);
    var inv: array<u32, 8> = pack_limbs_to_256(&inv20);

    // ---- backward peel ----
    for (var kk: u32 = 0u; kk < C; kk = kk + 1u) {
        let k = C - 1u - kk;
        let j2 = tid * C + k;
        let in_range = j2 < ppw;
        // inv_denom = 1 / denom_k = inv * prefix[k-1]; prefix[-1] is the
        // identity R (clamp the load index to 0 and select R when k == 0).
        let km1 = max(k, 1u) - 1u;
        let pp: array<u32, 8> = fr_select_f8(load_pref(scratch_base + km1), R, k == 0u);
        let inv_denom: array<u32, 8> = montgomery_product_f8(inv, pp);
{{#kind2}}
        let slot = base + (j2 + 1u) * pa;
        let present = in_range && (is_present[slot] != 0u);
        let xv: array<u32, 8> = load_x(slot, M);
        let yv: array<u32, 8> = load_y(slot, M);
        let real_denom: array<u32, 8> = fr_add_f8(yv, yv); // 2y
        let x2: array<u32, 8> = montgomery_product_f8(xv, xv);
        var num: array<u32, 8> = fr_add_f8(x2, x2);
        num = fr_add_f8(num, x2); // 3x^2
        let lambda: array<u32, 8> = montgomery_product_f8(num, inv_denom);
        let two_x: array<u32, 8> = fr_add_f8(xv, xv);
        var r_x: array<u32, 8> = montgomery_product_f8(lambda, lambda);
        r_x = fr_sub_f8(r_x, two_x);
        var r_y: array<u32, 8> = fr_sub_f8(xv, r_x);
        r_y = montgomery_product_f8(lambda, r_y);
        r_y = fr_sub_f8(r_y, yv);
        let out_x: array<u32, 8> = fr_select_f8(xv, r_x, present);
        let out_y: array<u32, 8> = fr_select_f8(yv, r_y, present);
        let denom_k: array<u32, 8> = fr_select_f8(R, real_denom, present);
        inv = montgomery_product_f8(inv, denom_k);
        if (in_range) {
            store_x(slot, M, out_x);
            store_y(slot, M, out_y);
        }
{{/kind2}}
{{^kind2}}
{{#kind0}}
        let src = base + j2 * pa + pb;
        let dst = base + j2 * pa + pb - 1u;
{{/kind0}}
{{#kind1}}
        let dst = base + 2u * j2 * pa;
        let src = base + (2u * j2 + 1u) * pa;
{{/kind1}}
        let ps = is_present[src] != 0u;
        let pl = is_present[dst] != 0u;
        let both = in_range && ps && pl;       // dst += src (affine add)
        let copy = in_range && ps && (!pl);    // dst = src (occupy empty slot)
        let x_d: array<u32, 8> = load_x(dst, M);
        let x_s: array<u32, 8> = load_x(src, M);
        let y_d: array<u32, 8> = load_y(dst, M);
        let y_s: array<u32, 8> = load_y(src, M);
        let dx: array<u32, 8> = fr_sub_f8(x_s, x_d);
        var lambda: array<u32, 8> = fr_sub_f8(y_s, y_d);
        lambda = montgomery_product_f8(lambda, inv_denom);
        var add_rx: array<u32, 8> = montgomery_product_f8(lambda, lambda);
        let x_sum: array<u32, 8> = fr_add_f8(x_d, x_s);
        add_rx = fr_sub_f8(add_rx, x_sum);
        var add_ry: array<u32, 8> = fr_sub_f8(x_d, add_rx);
        add_ry = montgomery_product_f8(lambda, add_ry);
        add_ry = fr_sub_f8(add_ry, y_d);
        var out_x: array<u32, 8> = fr_select_f8(x_d, x_s, copy);
        out_x = fr_select_f8(out_x, add_rx, both);
        var out_y: array<u32, 8> = fr_select_f8(y_d, y_s, copy);
        out_y = fr_select_f8(out_y, add_ry, both);
        let denom_k: array<u32, 8> = fr_select_f8(R, dx, both);
        inv = montgomery_product_f8(inv, denom_k);
        let new_present: u32 = select(u32(pl), 1u, copy);
        if (in_range) {
            store_x(dst, M, out_x);
            store_y(dst, M, out_y);
            is_present[dst] = new_present;
        }
{{/kind2}}
    }

    {{{ recompile }}}
}
`;

export const barrett = `const W_MASK = {{ w_mask }}u;
const SLACK = {{ slack }}u;

struct BigIntWide {
    limbs: array<u32, {{ num_words_mul_two }}>
}

fn get_mu() -> BigInt {
    var mu: BigInt;
{{{ mu_limbs }}}
    return mu;
}

fn get_p_wide() -> BigIntWide {
    var p: BigIntWide;
{{{ p_limbs }}}
    return p;
}

fn mul(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigIntWide {
    var res: BigIntWide;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        for (var j = 0u; j < NUM_WORDS; j = j + 1u) {
            let c = (*a).limbs[i] * (*b).limbs[j];
            res.limbs[i+j] += c & W_MASK;
            res.limbs[i+j+1] += c >> WORD_SIZE;
        }   
    }

    // start from 0 and carry the extra over to the next index
    for (var i = 0u; i < 2 * NUM_WORDS - 1; i = i + 1u) {
        res.limbs[i+1] += res.limbs[i] >> WORD_SIZE;
        res.limbs[i] = res.limbs[i] & W_MASK;
    }
    return res;
}

fn sub_512(a: ptr<function, BigIntWide>, b: ptr<function, BigIntWide>, res: ptr<function, BigIntWide>) -> u32 {
    var borrow = 0u;
    for (var i = 0u; i < 2u * NUM_WORDS; i = i + 1u) {
        (*res).limbs[i] = (*a).limbs[i] - (*b).limbs[i] - borrow;
        if ((*a).limbs[i] < ((*b).limbs[i] + borrow)) {
            (*res).limbs[i] += W_MASK + 1u;
            borrow = 1u;
        } else {
            borrow = 0u;
        }
    }
    return borrow;
}

fn get_higher_with_slack(a: ptr<function, BigIntWide>) -> BigInt {
    var out: BigInt;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        out.limbs[i] = (((*a).limbs[i + NUM_WORDS] << SLACK) + ((*a).limbs[i + NUM_WORDS - 1] >> (WORD_SIZE - SLACK))) & W_MASK;
    }
    return out;
}

fn field_mul(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigInt {
    var xy: BigIntWide = mul(a, b);
    var xy_hi: BigInt = get_higher_with_slack(&xy);
    var mu = get_mu();
    var l: BigIntWide = mul(&xy_hi, &mu);
    var l_hi: BigInt = get_higher_with_slack(&l);
    var p = get_p();
    var lp: BigIntWide = mul(&l_hi, &p);
    var r_wide: BigIntWide;
    sub_512(&xy, &lp, &r_wide);

    var r_wide_reduced: BigIntWide;
    var p_wide = get_p_wide();
    var underflow = sub_512(&r_wide, &p_wide, &r_wide_reduced);
    if (underflow == 0u) {
        r_wide = r_wide_reduced;
    }
    var r: BigInt;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        r.limbs[i] = r_wide.limbs[i];
    }
    return fr_reduce(&r);
}
`;

export const bucket_histogram = `// Per-bucket histogram of carry-free signed-Booth digits.
//
// Host mirror of \`buildInitCounts\` (msm_v2.ts): for every (point, window),
// extract the c-bit window plus its lookback bit, run the signed-Booth
// recode to get the absolute bucket index in [0, 2^(c-1)], and
// atomic-increment counts[w * BW + bucket]. BW comes in as a compile-time
// constant (matches the host-side \`m.BW\`).
//
// The dispatch is 2D: gid.x ranges over points, gid.y over windows. One
// thread per (point, window) — the same shape as the existing
// decompose_scalars_booth pass that runs at MSM-run time. The output is a
// flat NUM_WINDOWS × BW u32 array that MsmV2.prepare reads back and uses
// to plan the per-level pair/carry/stride counts.
//
// Tier 2 batch mode: when WINDOWS_PER_MSM < NUM_WINDOWS, the shader treats
// gid.y as a *virtual* window index spanning B*W effective windows. Each
// effective window y_eff decomposes into (b = y_eff / WINDOWS_PER_MSM, w =
// y_eff mod WINDOWS_PER_MSM), and reads scalar \`b * input_size + p\` for
// thread (p, y_eff). For B=1 (WINDOWS_PER_MSM == NUM_WINDOWS), b is always
// 0 and the formula collapses to the original single-MSM behaviour.
//
// Why we need this:
//   The host had been doing the same recode in JS — \`n × num_windows\`
//   iterations of integer math. At n=2^20 that is 17M iterations and
//   costs ~250 ms on the main thread, dominating \`prepare()\`. The GPU
//   does it in a few ms; the readback (NUM_WINDOWS × BW × 4 bytes ~=
//   2 MB at c=16) is cheap.
//
// Atomic contention: with BW ≈ 32k buckets per window and ~n/BW ≈ 32
// scalars hitting each bucket at n=2^20 with uniform Fr scalars, atomic
// pressure is low. Adversarial distributions would serialize, but the
// bridge's contract (MsmV2 only sees scalars from real Fr commits) makes
// this a non-issue.

const BW: u32 = {{ buckets_per_window }}u;
// Number of Pippenger windows per individual MSM. For single-MSM (B=1) use
// this equals the total dispatch's num_windows; for batch mode (B>1) it is
// the per-MSM W and total dispatch num_windows = B * WINDOWS_PER_MSM.
const WINDOWS_PER_MSM: u32 = {{ windows_per_msm }}u;

@group(0) @binding(0) var<storage, read>           scalars: array<u32>;
@group(0) @binding(1) var<storage, read_write>     counts:  array<atomic<u32>>;
@group(0) @binding(2) var<uniform>                 params:  vec4<u32>;
// params.x = input_size   (n)
// params.y = num_windows
// params.z = window_bits  (c)
// params.w = scalar_words (u32 words per scalar, always 8 for BN254)

const WORD_BITS: u32 = 32u;

// Adreno-safe variable shifts (barrel shifter): a runtime shift amount s in
// [0,31] as <= 5 constant-amount shifts. Adreno 7xx (Galaxy S23 / Adreno 740)
// miscompiles runtime shift amounts; constant amounts fold cleanly. Bit-
// identical to \`x >> s\` / \`x << s\` for s in [0,31]. Kept in sync with the copy
// in decompose_scalars_booth (see integration/S23_ADRENO740_CORRECTNESS.md).
fn shr_var(x: u32, s: u32) -> u32 {
    var r = x;
    if ((s & 16u) != 0u) { r = r >> 16u; }
    if ((s & 8u) != 0u) { r = r >> 8u; }
    if ((s & 4u) != 0u) { r = r >> 4u; }
    if ((s & 2u) != 0u) { r = r >> 2u; }
    if ((s & 1u) != 0u) { r = r >> 1u; }
    return r;
}
fn shl_var(x: u32, s: u32) -> u32 {
    var r = x;
    if ((s & 16u) != 0u) { r = r << 16u; }
    if ((s & 8u) != 0u) { r = r << 8u; }
    if ((s & 4u) != 0u) { r = r << 4u; }
    if ((s & 2u) != 0u) { r = r << 2u; }
    if ((s & 1u) != 0u) { r = r << 1u; }
    return r;
}

// Same \`read_bits\` as decompose_scalars_booth — kept inline so the two
// shaders stay independently editable. Reads \`count\` bits at absolute
// bit \`bit_off\` in scalar \`s\`, little-endian; bits past the scalar's
// words read as 0. Variable shifts go through shr_var/shl_var (Adreno-740).
fn read_bits(s: u32, scalar_words: u32, bit_off: u32, count: u32) -> u32 {
    let base = s * scalar_words;
    let word = bit_off / WORD_BITS;
    let off = bit_off % WORD_BITS;
    var v: u32 = 0u;
    if (word < scalar_words) {
        v = shr_var(scalars[base + word], off);
    }
    if (off + count > WORD_BITS && word + 1u < scalar_words) {
        v = v | shl_var(scalars[base + word + 1u], WORD_BITS - off);
    }
    if (count >= WORD_BITS) {
        return v;
    }
    return v & (shl_var(1u, count) - 1u);
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let p = gid.x;
    let y_eff = gid.y;
    let input_size = params.x;
    let num_windows = params.y;
    if (p >= input_size || y_eff >= num_windows) {
        return;
    }
    let c = params.z;
    let scalar_words = params.w;

    // Tier-2 virtual-window split: y_eff = b * WINDOWS_PER_MSM + w.
    // For B=1 (WINDOWS_PER_MSM == num_windows), b is always 0 and w = y_eff —
    // identical to the single-MSM behaviour.
    let b = y_eff / WINDOWS_PER_MSM;
    let w = y_eff % WINDOWS_PER_MSM;
    let scalar_idx = b * input_size + p;

    let win_bits = read_bits(scalar_idx, scalar_words, w * c, c);
    var lookback: u32 = 0u;
    if (w > 0u) {
        lookback = read_bits(scalar_idx, scalar_words, w * c - 1u, 1u);
    }
    let raw = (win_bits << 1u) | lookback;

    // Constantine signedWindowEncoding: bit c of raw is the sign; the
    // magnitude is the conditionally-negated (raw + 1) >> 1.
    let neg = shr_var(raw, c) & 1u;
    let neg_mask = 0u - neg;
    let val_mask = shl_var(1u, c) - 1u;
    let encode = (raw + 1u) >> 1u;
    let bucket = ((encode - neg) ^ neg_mask) & val_mask;

    atomicAdd(&counts[y_eff * BW + bucket], 1u);

    {{{ recompile }}}
}
`;

export const convert_points_only = `// Point-only variant of \`convert_point_coords_and_decompose_scalars\`.
// Reads raw affine (x, y) pairs from two packed u32 buffers and writes
// Montgomery-form (x·R mod q, y·R mod q) BigInts.
//
// Purpose. When the caller holds a persistent GPU context and the base
// points are SRS-backed (i.e. stable across many MSM calls), we want to
// pay the Barrett + Montgomery conversion cost **once** at SRS upload,
// not on every MSM. This shader is the Stage-1 conversion without the
// scalar-decomposition side effect.

{{> structs }}
{{> bigint_funcs }}
{{> field_funcs }}
{{> barrett_funcs }}
{{> montgomery_product_funcs }}
{{ > extract_word_from_bytes_le_funcs }}

@group(0) @binding(0)
var<storage, read> first_half: array<u32>;
@group(0) @binding(1)
var<storage, read> second_half: array<u32>;

{{#packed}}
@group(0) @binding(2)
var<storage, read_write> point_x: array<vec4<u32>>;
@group(0) @binding(3)
var<storage, read_write> point_y: array<vec4<u32>>;
{{/packed}}
{{^packed}}
@group(0) @binding(2)
var<storage, read_write> point_x: array<BigInt>;
@group(0) @binding(3)
var<storage, read_write> point_y: array<BigInt>;
{{/packed}}

@group(0) @binding(4)
var<uniform> input_size: u32;

{{#packed}}
{{{ dec_pack }}}

fn store_packed_pt(base_elem: u32, src: ptr<storage, array<vec4<u32>>, read_write>, val: ptr<function, BigInt>) {
    let w = pack_limbs_to_256(val);
    (*src)[2u * base_elem] = vec4<u32>(w[0], w[1], w[2], w[3]);
    (*src)[2u * base_elem + 1u] = vec4<u32>(w[4], w[5], w[6], w[7]);
}
{{/packed}}

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let gidx = global_id.x;
    let gidy = global_id.y;
    let id = gidx * {{ num_y_workgroups }}u + gidy;

    let INPUT_SIZE = input_size;
    let NUM_16_BIT_WORDS_PER_COORD = {{ num_16_bit_words_per_coord }}u;
    // Dispatcher rounds totalThreads up to a multiple of (workgroup_size *
    // numXWorkgroups * numYWorkgroups) so the tile covers srsN; ids past
    // input_size are no-ops. Without this guard a non-power-of-two srsN
    // (e.g. 88_899 for the ECDSA-r1 transfer flow) would OOB-write past
    // the point_x / point_y buffers.
    if (id >= INPUT_SIZE) {
        return;
    }

    var x_bytes: array<u32, {{ num_16_bit_words_per_coord }}>;
    var y_bytes: array<u32, {{ num_16_bit_words_per_coord }}>;
    var h = INPUT_SIZE / 2u;

    for (var i = 0u; i < {{ coord_u32_words }}u; i ++) {
        var x: u32;
        var y: u32;

        if (id < h) {
            x = first_half[id * {{ coord_u32_words_mul_two }}u + i];
            y = first_half[id * {{ coord_u32_words_mul_two }}u + i + {{ coord_u32_words }}u];
        } else {
            x = second_half[(id - h) * {{ coord_u32_words_mul_two }}u + i];
            y = second_half[(id - h) * {{ coord_u32_words_mul_two }}u + i + {{ coord_u32_words }}u];
        }

        x_bytes[NUM_16_BIT_WORDS_PER_COORD - 1 - (i * 2)] = x & 65535u;
        x_bytes[NUM_16_BIT_WORDS_PER_COORD - 1 - (i * 2) - 1] = x >> 16u;

        y_bytes[NUM_16_BIT_WORDS_PER_COORD - 1 - (i * 2)] = y & 65535u;
        y_bytes[NUM_16_BIT_WORDS_PER_COORD - 1 - (i * 2) - 1] = y >> 16u;
    }

    var x_bigint: BigInt;
    var y_bigint: BigInt;
    for (var i = 0u; i < NUM_WORDS; i ++) {
        x_bigint.limbs[i] = extract_word_from_coord_bytes_le(x_bytes, i, WORD_SIZE);
        y_bigint.limbs[i] = extract_word_from_coord_bytes_le(y_bytes, i, WORD_SIZE);
    }

    var r = get_r();
    var x_mont = field_mul(&x_bigint, &r);
    var y_mont = field_mul(&y_bigint, &r);
{{#packed}}
    store_packed_pt(id, &point_x, &x_mont);
    store_packed_pt(id, &point_y, &y_mont);
{{/packed}}
{{^packed}}
    point_x[id] = x_mont;
    point_y[id] = y_mont;
{{/packed}}

    {{{ recompile }}}
}
`;

export const csr_to_v2_active_sums = `// Layout converter for the v2 pair-tree MSM bucket-accumulate path.
//
// Materializes the bucket-major active_sums buffer — in the 2-plane SoA
// layout the v2 pair-tree consumes — by copying packed 8-u32 base coords
// from new_point_x / new_point_y at the indices listed in val_idx (cuZK
// transpose output, bucket-major per subtask).
//
// active_sums layout: ONE buffer, two planes. PG = 2 vec4 per element;
// plane p (0 = x, 1 = y) base = p * PG * M, where M is the element
// stride. Element e of plane p occupies vec4 indices p*PG*M + PG*e + {0,1}.
//
// Per slot k in [0, total_slots): pt_idx = val_idx[k]; copy
// new_point_x[pt_idx] -> plane 0 slot k, new_point_y[pt_idx] -> plane 1.
// The slot index is global: subtask s contributes slots
// [s*input_size, (s+1)*input_size), and input_size matches the v2
// per-window stride, so the slot IS the active_sums element index.
//
// Sign handling: rendered with \`with_sign\` when fed by the carry-free
// signed-Booth decompose, which emits a per-(window, point) packed entry
// in \`bucket_and_sign\`. The sign lives at bit 31; a 1 means the point
// is added negated, so the y plane is sourced from new_point_y_neg (the
// precomputed field negation -y); x is unchanged. Without \`with_sign\`
// the converter is a plain copy (cuZK's signed-slice path folds the
// sign into the bucket).
//
// Lever B (\`index_mode\`): instead of materializing a 64-byte point per
// slot, write a 4-byte value — the point index in the low 31 bits, the
// sign bit in bit 31. active_sums is then a flat u32 array, 16x smaller.
// The level-0 pair-tree kernels (fused / carry / finalize, l0_index_mode)
// gather the actual point from the pool and negate y on the sign bit.
{{#index_mode}}
@group(0) @binding(0) var<storage, read>       val_idx:     array<u32>;
@group(0) @binding(1) var<storage, read_write> active_sums: array<u32>;
// params[0] = total_slots
// params[1] = base_offset (added to every pt_idx so the L0 pair-tree shaders
//             gather from \`pool[pt_idx + base_offset]\`; lets a single uploaded
//             SRS pool serve every commit regardless of the polynomial's
//             start_index in the C++ SRS)
// params[2] = wstride
// params[3] = input_size
@group(0) @binding(2) var<uniform>             params:          vec4<u32>;
// One u32 per (window, point): low 31 bits = bucket index (we don't need
// it here), bit 31 = sign. Replaces the old \`signs: array<u32>\` buffer —
// the bucket and sign are packed at decompose time to halve the working set.
@group(0) @binding(3) var<storage, read>       bucket_and_sign: array<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let slot = gid.x;
    if (slot >= params[0]) {
        return;
    }
    let pt_idx = val_idx[slot];
    let window = slot / params[2];
    // Sign bit lives at bit 31 of the packed entry; constant-shift extract.
    let neg = bucket_and_sign[window * params[3] + pt_idx] >> 31u;
    // Bake the SRS base_offset into the index BEFORE storing — downstream L0
    // shaders (ba_fused_super, ba_carry_copy, ba_finalize) gather points via
    // \`point_x[2 * (active_sums[idx] & L0_IDX_MASK)]\` without touching the
    // offset themselves. 31 bits of address space (max ~2.1B) is plenty for
    // any realistic SRS size.
    let pt_real = pt_idx + params[1];
    active_sums[slot] = pt_real | (neg << 31u);

    {{{ recompile }}}
}
{{/index_mode}}
{{^index_mode}}
@group(0) @binding(0)
var<storage, read> val_idx: array<u32>;
@group(0) @binding(1)
var<storage, read> new_point_x: array<vec4<u32>>;
@group(0) @binding(2)
var<storage, read> new_point_y: array<vec4<u32>>;
@group(0) @binding(3)
var<storage, read_write> active_sums: array<vec4<u32>>;

// params[0] = total_slots (num_subtasks * input_size)
// params[1] = M           (active_sums element stride; plane stride = PG*M)
// params[2] = wstride     (per-window slot stride; with_sign only)
// params[3] = input_size  (bucket_and_sign stride = per-window point count; with_sign)
@group(0) @binding(4)
var<uniform> params: vec4<u32>;
{{#with_sign}}
// Precomputed field negation -y of every pool point, same layout as
// new_point_y; selected per slot when the digit sign bit is set.
@group(0) @binding(5)
var<storage, read> new_point_y_neg: array<vec4<u32>>;
// bucket_and_sign[window*input_size + pt_idx]: bit 31 = sign (1 => negate y).
// We only consume the sign here; the bucket bits were used by the transpose
// to build the CSR. See decompose_scalars_booth header for the packing.
@group(0) @binding(6)
var<storage, read> bucket_and_sign: array<u32>;
{{/with_sign}}

const PG: u32 = 2u;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let slot = gid.x;
    let total = params[0];
    if (slot >= total) {
        return;
    }
    let m = params[1];

    let pt_idx = val_idx[slot];
    let x_base = PG * slot;
    let y_base = PG * m + PG * slot;

    active_sums[x_base]      = new_point_x[2u * pt_idx];
    active_sums[x_base + 1u] = new_point_x[2u * pt_idx + 1u];
{{#with_sign}}
    let window = slot / params[2];
    // Sign bit lives at bit 31 of the packed entry; constant-shift extract.
    let neg = bucket_and_sign[window * params[3] + pt_idx] >> 31u;
    if (neg == 1u) {
        active_sums[y_base]      = new_point_y_neg[2u * pt_idx];
        active_sums[y_base + 1u] = new_point_y_neg[2u * pt_idx + 1u];
    } else {
        active_sums[y_base]      = new_point_y[2u * pt_idx];
        active_sums[y_base + 1u] = new_point_y[2u * pt_idx + 1u];
    }
{{/with_sign}}
{{^with_sign}}
    active_sums[y_base]      = new_point_y[2u * pt_idx];
    active_sums[y_base + 1u] = new_point_y[2u * pt_idx + 1u];
{{/with_sign}}

    {{{ recompile }}}
}
{{/index_mode}}
`;

export const csr_to_v2_meta = `// Companion to csr_to_v2_active_sums: derives the per-bucket counts and
// GLOBAL offsets that drive the v2 pair-tree planner.
//
// row_ptr layout: per subtask, num_columns + 1 entries forming a
// CSR-style prefix sum. row_ptr[s*(num_columns+1) + b + 1] -
// row_ptr[s*(num_columns+1) + b] is bucket b's count; the begin value is
// the subtask-relative start within val_idx / active_sums.
//
// The v2 planner indexes counts/offsets by global bucket id and expects
// offsets in the global active_sums element space, so this shader adds
// subtask * input_size to the subtask-relative begin.
//
// One thread per (subtask, bucket) emits one (count, offset) pair.

@group(0) @binding(0)
var<storage, read> row_ptr: array<u32>;
@group(0) @binding(1)
var<storage, read_write> active_counts: array<u32>;
@group(0) @binding(2)
var<storage, read_write> active_offsets: array<u32>;

// params[0] = num_columns
// params[1] = total_buckets (num_subtasks * num_columns)
// params[2] = input_size   (per-subtask slot stride; globalises offsets)
@group(0) @binding(3)
var<uniform> params: vec4<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let id = gid.x;
    let total = params[1];
    if (id >= total) {
        return;
    }

    let num_columns = params[0];
    let input_size = params[2];
    let subtask = id / num_columns;
    let bucket_local = id % num_columns;
    let rp_offset = subtask * (num_columns + 1u);

    let begin = row_ptr[rp_offset + bucket_local];
    let end = row_ptr[rp_offset + bucket_local + 1u];

    active_counts[id] = end - begin;
    active_offsets[id] = subtask * input_size + begin;

    {{{ recompile }}}
}
`;

export const decompose_scalars_booth = `// Carry-free signed-Booth window decompose.
//
// Port of Constantine's signedWindowEncoding (barretenberg C++
// scalar_multiplication.cpp, get_constantine_packed_digit). A c-bit
// window's signed digit is a pure function of c+1 bits: the window's own
// c bits plus the top bit of the window below it (the "lookback" bit,
// a synthetic 0 for the bottom window). Reading that one shared bit is
// what removes the carry chain a plain signed-digit recoder needs — so
// every (point, window) digit is independent and the kernel is
// embarrassingly parallel.
//
// Per (window, point) it writes one u32: bits [0..30] hold the bucket index
// in [0, 2^(c-1)] (0 is the zero digit), bit 31 holds the sign (1 => negate
// the point in this window). Packing both into one buffer (instead of two
// parallel u32 arrays) halves the (window × point) working set — for n=131k
// that's ~10MB less GPU memory. The transpose phase reads the bucket via
// \`entry & 0x7FFFFFFFu\`; the csr_to_v2 gather reads the sign via
// \`entry >> 31u\`. Scalars must be in normal (non-Montgomery) form.
//
// Why the sign sits at bit 31 (a literal) and not at bit \`c\` (a uniform):
// Adreno's WGSL compiler (Galaxy S25, etc.) is unreliable for runtime
// shift amounts — \`(neg << c)\` where \`c\` comes from a uniform produces
// either garbage or compile errors. Bit 31 is a literal, Tint folds it
// into a constant-shift instruction, every driver handles it cleanly. We
// have plenty of headroom: pickC() caps c at 15, so bucket < 2^15 and
// bits [15..30] are unused but harmless.
//
// Tier 2 batch mode: when WINDOWS_PER_MSM < total dispatch num_windows, the
// global window index \`w_global = gid.y + batch_window_base\` is interpreted
// as a *virtual* index spanning B*W effective windows. It splits into
// (b = w_global / WINDOWS_PER_MSM, w = w_global mod WINDOWS_PER_MSM); the
// thread reads scalar \`b * input_size + p\` and bits at offset \`w * c\`.
// bucket_and_sign is still written at the batch-local \`gid.y * input_size +
// p\` (the downstream pipeline is oblivious to MSM identity). For B=1
// (WINDOWS_PER_MSM == total num_windows), b is always 0 and w = w_global —
// identical to the single-MSM behaviour.

@group(0) @binding(0) var<storage, read>       scalars:         array<u32>;
@group(0) @binding(1) var<storage, read_write> bucket_and_sign: array<u32>;
@group(0) @binding(2) var<uniform>             params:          vec4<u32>;
// params.x = input_size   (points per MSM — also points per window)
// params.y = num_windows  (windows in this dispatch batch)
// params.z = window_bits  (c)
// params.w = scalar_words (u32 words per scalar)
// Lever G (window batching): batch.x = batch_window_base, the global
// index of this dispatch-batch's first effective window. Window bits are
// sliced at the GLOBAL effective window index (gid.y + batch_window_base);
// bucket_and_sign is written at the batch-local index (gid.y).
@group(0) @binding(3) var<uniform>             batch:           vec4<u32>;

// Per-MSM windows. For single-MSM (B=1) this equals the host's
// \`m.numWindows\`; for batch mode it is the per-MSM W and the total
// effective window count is \`B * WINDOWS_PER_MSM\`.
const WINDOWS_PER_MSM: u32 = {{ windows_per_msm }}u;

const WORD_BITS: u32 = 32u;

// Adreno-safe variable shifts: express a runtime shift amount s in [0,31] as
// <= 5 constant-amount shifts (a barrel shifter). Adreno 7xx (Galaxy S23 /
// Adreno 740) miscompiles runtime shift amounts — the same reason the sign was
// packed at the literal bit 31 below — while constant amounts fold cleanly on
// every driver. Bit-identical to \`x >> s\` / \`x << s\` for s in [0,31] on a
// conformant target (see integration/S23_ADRENO740_CORRECTNESS.md).
fn shr_var(x: u32, s: u32) -> u32 {
    var r = x;
    if ((s & 16u) != 0u) { r = r >> 16u; }
    if ((s & 8u) != 0u) { r = r >> 8u; }
    if ((s & 4u) != 0u) { r = r >> 4u; }
    if ((s & 2u) != 0u) { r = r >> 2u; }
    if ((s & 1u) != 0u) { r = r >> 1u; }
    return r;
}
fn shl_var(x: u32, s: u32) -> u32 {
    var r = x;
    if ((s & 16u) != 0u) { r = r << 16u; }
    if ((s & 8u) != 0u) { r = r << 8u; }
    if ((s & 4u) != 0u) { r = r << 4u; }
    if ((s & 2u) != 0u) { r = r << 2u; }
    if ((s & 1u) != 0u) { r = r << 1u; }
    return r;
}

// Read \`count\` (<= 32) bits at absolute bit \`bit_off\` from scalar \`s\`,
// little-endian. Bits past the scalar's words read as 0. Variable shifts go
// through shr_var/shl_var (Adreno-740 correctness).
fn read_bits(s: u32, scalar_words: u32, bit_off: u32, count: u32) -> u32 {
    let base = s * scalar_words;
    let word = bit_off / WORD_BITS;
    let off = bit_off % WORD_BITS;
    var v: u32 = 0u;
    if (word < scalar_words) {
        v = shr_var(scalars[base + word], off);
    }
    if (off + count > WORD_BITS && word + 1u < scalar_words) {
        v = v | shl_var(scalars[base + word + 1u], WORD_BITS - off);
    }
    if (count >= WORD_BITS) {
        return v;
    }
    return v & (shl_var(1u, count) - 1u);
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let p = gid.x;
    let w_local = gid.y;
    let input_size = params.x;
    let num_windows = params.y;
    if (p >= input_size || w_local >= num_windows) {
        return;
    }
    let c = params.z;
    let scalar_words = params.w;
    let w_global = w_local + batch.x;

    // Tier-2 virtual-window split: w_global = b * WINDOWS_PER_MSM + w.
    // Lookback is 0 at w==0 (the bottom window of each MSM's scalar) — not
    // at w_global==0. Each MSM b reads bits from scalar \`b * input_size + p\`.
    let b = w_global / WINDOWS_PER_MSM;
    let w = w_global % WINDOWS_PER_MSM;
    let scalar_idx = b * input_size + p;

    // c+1-bit window: the window's c bits, with the lookback bit (top bit
    // of the window below in the same scalar; synthetic 0 for window 0) as
    // the LSB.
    let win_bits = read_bits(scalar_idx, scalar_words, w * c, c);
    var lookback: u32 = 0u;
    if (w > 0u) {
        lookback = read_bits(scalar_idx, scalar_words, w * c - 1u, 1u);
    }
    let raw = (win_bits << 1u) | lookback;

    // Constantine signedWindowEncoding: bit c of raw is the sign; the
    // magnitude is the conditionally-negated (raw + 1) >> 1.
    let neg = shr_var(raw, c) & 1u;
    let neg_mask = 0u - neg;            // 0 or 0xFFFFFFFF
    let val_mask = shl_var(1u, c) - 1u;
    let encode = (raw + 1u) >> 1u;
    let bucket = ((encode - neg) ^ neg_mask) & val_mask;

    let idx = w_local * input_size + p;
    // Pack: bucket in low bits, sign in bit 31. Constant shift — works on
    // Adreno (see header).
    bucket_and_sign[idx] = bucket | (neg << 31u);

    {{{ recompile }}}
}
`;

export const decompress_g1_bn254 = `// GPU SRS decompression for BN254 G1, compressed format.
//
// Replaces the JS bigint sqrt loop in dev/msm-webgpu/srs.ts. Each
// compressed point is 32 BE bytes: the top bit of byte 0 is the parity
// of y, the bottom 255 bits hold x. We recover y from
//
//     y = (x^3 + 3)^((q+1)/4)   (q ≡ 3 mod 4, BN254 b = 3)
//
// and flip its sign to match the encoded parity bit, then write affine
// (x, y) as interleaved 32 LE bytes each.
//
// All field work is in Montgomery form; the heavy lifting is one
// \`fr_pow\` per point (~260 squarings + ~126 mults for a 252-bit
// exponent). One thread per point.

{{> structs }}
{{> bigint_funcs }}
{{> field_funcs }}
{{> barrett_funcs }}
{{> montgomery_product_funcs }}
{{> fr_pow_funcs }}

// 32 bytes per point, with the BE input reversed by the host so that
// compressed_in[id*8 + i] is the i'th LE u32 of the value (low chunk
// first). The shader can therefore read words natively without any
// per-word byte-swap.
@group(0) @binding(0)
var<storage, read> compressed_in: array<u32>;

// 64 LE bytes per point, packed as 16 u32s where each u32 holds 4 LE
// bytes. First 8 u32s are x (LSB first), next 8 are y. Matches the JS
// \`writeLe32\` interleaved layout the convert+decompose shader expects.
@group(0) @binding(1)
var<storage, read_write> affine_out: array<u32>;

@group(0) @binding(2)
var<uniform> input_size: u32;

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

// Montgomery form of 3 (the curve b parameter). Used in y² = x³ + 3.
fn get_b3_mont() -> BigInt {
    var b3: BigInt;
{{{ b3_mont_limbs }}}
    return b3;
}

// (q + 1) / 4. The exponent for the closed-form sqrt over a field of
// characteristic q ≡ 3 (mod 4).
fn get_sqrt_exp() -> BigInt {
    var e: BigInt;
{{{ sqrt_exp_limbs }}}
    return e;
}

// Extract the limb_idx'th WORD_SIZE-bit limb from 9 LE u32s holding the
// 256-bit native value (le_words[0] is the LSB u32). Up to two adjacent
// u32s are read; the 9th entry is a zero pad so the highest limb never
// needs a bounds check on the read.
fn extract_limb_le(le_words: ptr<function, array<u32, 9>>, limb_idx: u32) -> u32 {
    let bit_start = limb_idx * WORD_SIZE;
    let word_idx = bit_start / 32u;
    let bit_off = bit_start - word_idx * 32u;
    let lo = (*le_words)[word_idx] >> bit_off;
    var hi: u32 = 0u;
    // bit_off + WORD_SIZE crosses the 32-bit boundary when bit_off > 32 - WORD_SIZE
    // (= 19 for WORD_SIZE=13). The shift \`32 - bit_off\` is in [1, 12] there,
    // so it's well-defined; the alternative branch would attempt \`<< 32u\`.
    if (bit_off + WORD_SIZE > 32u) {
        hi = (*le_words)[word_idx + 1u] << (32u - bit_off);
    }
    return (lo | hi) & MASK;
}

// Inverse of \`extract_limb_le\`: gather bits [word_idx*32, word_idx*32 + 32)
// from the 13-bit limbs of \`x\` and pack them as an LE u32. A 32-bit
// window spans 3 or 4 13-bit limbs depending on bit_off; we always
// fold in 3 limbs and conditionally add a 4th when those don't cover
// the full 32 bits. The 4th limb is only needed for word_idx ∈ {2,4,6}
// (bit_off > 7); in those cases limb_idx_lo + 3 ≤ 17 < NUM_WORDS so
// the access is safe. For word_idx ∈ {1,3,5,7} the conditional is
// false and we skip the (would-be out-of-bounds for word_idx=7) read.
fn limbs_to_le_u32(x: ptr<function, BigInt>, word_idx: u32) -> u32 {
    let bit_start = word_idx * 32u;
    let limb_idx_lo = bit_start / WORD_SIZE;
    let bit_off = bit_start - limb_idx_lo * WORD_SIZE;
    // First limb: shift down by bit_off so its bits land at the bottom of acc.
    var acc: u32 = (*x).limbs[limb_idx_lo] >> bit_off;
    var bits: u32 = WORD_SIZE - bit_off;          // valid bits in acc; in [1, 13]
    acc = acc | ((*x).limbs[limb_idx_lo + 1u] << bits);
    bits = bits + WORD_SIZE;                       // in [14, 26]
    acc = acc | ((*x).limbs[limb_idx_lo + 2u] << bits);
    bits = bits + WORD_SIZE;                       // in [27, 39]
    if (bits < 32u) {
        acc = acc | ((*x).limbs[limb_idx_lo + 3u] << bits);
    }
    return acc;
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let id = global_id.x;
    if (id >= input_size) { return; }

    // Load the 8 LE u32s for this point. The host already byte-reversed
    // the original BE encoding so these are in natural LE order
    // (le_words[0] = low 32 bits, le_words[7] = high 32 bits). The 9th
    // slot is a zero pad so \`extract_limb_le\` never needs a bounds
    // branch when limb 19 spans the top of the value.
    var le_words: array<u32, 9>;
    for (var i = 0u; i < 8u; i = i + 1u) {
        le_words[i] = compressed_in[id * 8u + i];
    }
    le_words[8] = 0u;

    // The parity bit is the MSB of the top BE byte = bit 31 of the
    // top LE u32 (le_words[7]). Clear it from the value.
    let y_bit: u32 = (le_words[7] >> 31u) & 1u;
    le_words[7] = le_words[7] & 0x7fffffffu;

    // x's LE-u32 representation is just le_words[0..8] (with the sign
    // bit already cleared from le_words[7]). Snapshot it directly here
    // — no round trip through 13-bit limbs needed for the output, and
    // skipping that round trip empirically also avoids a WGSL/Tint
    // pattern where calling \`limbs_to_le_u32(&x_native, …)\` before
    // \`field_mul\` corrupts x_native (and therefore everything
    // downstream, including y).
    var x_out: array<u32, 8>;
    for (var i = 0u; i < 8u; i = i + 1u) {
        x_out[i] = le_words[i];
    }

    // Assemble x in native form: 20 WORD_SIZE-bit limbs (for the math).
    var x_native: BigInt;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        x_native.limbs[i] = extract_limb_le(&le_words, i);
    }

    // Convert x to Montgomery form: x_mont = x · R mod p (Barrett mul).
    var r = get_r();
    var x_mont: BigInt = field_mul(&x_native, &r);

    // y²_mont = x_mont³ + 3·R mod p.
    var x_sq_mont: BigInt = montgomery_product(&x_mont, &x_mont);
    var x_cu_mont: BigInt = montgomery_product(&x_sq_mont, &x_mont);
    var b3_mont: BigInt = get_b3_mont();
    var y_sq_mont: BigInt = fr_add(&x_cu_mont, &b3_mont);

    // y_mont = (y²_mont)^((q+1)/4) — closed-form sqrt for q ≡ 3 (mod 4).
    var sqrt_exp: BigInt = get_sqrt_exp();
    var y_mont: BigInt = fr_pow(y_sq_mont, sqrt_exp);

    // Convert y back to native: mp(y_mont, 1) = y_mont · 1 · R^(-1) = y.
    var one_native: BigInt;
    one_native.limbs[0] = 1u;
    var y_native: BigInt = montgomery_product(&y_mont, &one_native);

    // Parity flip: if recovered parity disagrees with encoded, negate
    // mod p. SRS points are non-zero affine, so y_native != 0 and the
    // bare subtraction is always canonical.
    let parity: u32 = y_native.limbs[0] & 1u;
    if (parity != y_bit) {
        var p_const: BigInt = get_p();
        var neg: BigInt;
        let _b = bigint_sub(&p_const, &y_native, &neg);
        y_native = neg;
    }

    // Write 8 LE u32s for x (pre-packed at the top), then 8 for y.
    // 16 u32s per point.
    let out_base = id * 16u;
    for (var i = 0u; i < 8u; i = i + 1u) {
        affine_out[out_base + i] = x_out[i];
    }
    for (var i = 0u; i < 8u; i = i + 1u) {
        affine_out[out_base + 8u + i] = limbs_to_le_u32(&y_native, i);
    }

    {{{ recompile }}}
}
`;

export const extract_word_from_bytes_le = `fn extract_word_from_coord_bytes_le(
    input: array<u32, {{ num_16_bit_words_per_coord }}>,
    word_idx: u32,
    chunk_size: u32
) -> u32 {
    var word = 0u;
    let start_byte_idx = {{ num_16_bit_words_per_coord }}u - 1u - ((word_idx * chunk_size + chunk_size) / 16u);
    let end_byte_idx = {{ num_16_bit_words_per_coord }}u - 1u - ((word_idx * chunk_size) / 16u);

    let start_byte_offset = (word_idx * chunk_size + chunk_size) % 16u;
    let end_byte_offset = (word_idx * chunk_size) % 16u;

    var mask = 0u;
    if (start_byte_offset > 0u) {
        mask = (2u << (start_byte_offset - 1u)) - 1u;
    }
    if (start_byte_idx == end_byte_idx) {
        word = (input[start_byte_idx] & mask) >> end_byte_offset;
    } else {
        word = (input[start_byte_idx] & mask) << (16u - end_byte_offset);
        word += input[end_byte_idx] >> end_byte_offset;
    }

    return word;
}

fn extract_word_from_bytes_le(
    input: array<u32, 16>,
    word_idx: u32,
    chunk_size: u32
) -> u32 {
    var word = 0u;
    let start_byte_idx = 15u - ((word_idx * chunk_size + chunk_size) / 16u);
    let end_byte_idx = 15u - ((word_idx * chunk_size) / 16u);

    let start_byte_offset = (word_idx * chunk_size + chunk_size) % 16u;
    let end_byte_offset = (word_idx * chunk_size) % 16u;

    var mask = 0u;
    if (start_byte_offset > 0u) {
        mask = (2u << (start_byte_offset - 1u)) - 1u;
    }
    if (start_byte_idx == end_byte_idx) {
        word = (input[start_byte_idx] & mask) >> end_byte_offset;
    } else {
        word = (input[start_byte_idx] & mask) << (16u - end_byte_offset);
        word += input[end_byte_idx] >> end_byte_offset;
    }

    return word;
}
`;

export const mask_scalars = `// Additive scalar-masking pre-pass for the WebGPU MSM.
//
// Rewrites each scalar s_i in place to (s_i + R_{srs_offset + p}) mod r, where
// R is a fixed per-SRS-position random vector and r is the BN254 scalar field
// modulus. Masking turns the structured scalars (small / sparse / heavily
// repeated — the translator range-constraint polynomials) that the bucket
// accumulation pair-tree mishandles into uniform full-width scalars, which is
// the case MsmV2 is known to compute correctly. The host then recovers the
// true commitment C = C' - O by subtracting the precomputed offset
// O = sum_i R_i * P_i (one point per (srs_offset, n) point set).
//
// Dispatched BEFORE the bucket histogram in prepare(), so every downstream
// stage (histogram, level planning, Booth decompose) reads the masked scalars.
// Scalars are in normal (non-Montgomery) form, 8 little-endian u32 limbs each;
// R is generated in the same form. p = i mod input_size is the point index
// within the MSM, so every batch slot b (scalar i = b*input_size + p) is masked
// with the SAME R[srs_offset + p] — matching the single shared offset O that is
// subtracted from each slot's window-0 sum.
//
// Limb arithmetic mirrors field8's fr_add_f8: WGSL has no add-with-carry, so
// the carry out of each word is u32(sum < operand). The loop is unrolled with
// literal indices (no runtime-indexed arrays) — the same Adreno-safe idiom the
// rest of the MSM shaders use.

@group(0) @binding(0) var<storage, read_write> scalars: array<u32>;
@group(0) @binding(1) var<storage, read>       mask:    array<u32>;
@group(0) @binding(2) var<uniform>             params:  vec4<u32>;
// params.x = total_scalars (batchSize * input_size)
// params.y = input_size    (points per MSM, also the slot stride)
// params.z = srs_offset    (mask index base for point 0 of each slot)
// params.w = scalar_words  (must be 8)

const WORDS: u32 = 8u;

// BN254 scalar field modulus r as eight little-endian 32-bit words.
// r = 0x30644e72e131a029b85045b68181585d2833e84879b9709143e1f593f0000001
const R8_0: u32 = 0xf0000001u;
const R8_1: u32 = 0x43e1f593u;
const R8_2: u32 = 0x79b97091u;
const R8_3: u32 = 0x2833e848u;
const R8_4: u32 = 0x8181585du;
const R8_5: u32 = 0xb85045b6u;
const R8_6: u32 = 0xe131a029u;
const R8_7: u32 = 0x30644e72u;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.x) {
        return;
    }
    let input_size = params.y;
    let srs_offset = params.z;
    let p = i % input_size;
    let s_base = i * WORDS;
    let m_base = (srs_offset + p) * WORDS;

    // Load operands (a = scalar, b = mask), both in [0, r).
    let a0 = scalars[s_base + 0u]; let b0 = mask[m_base + 0u];
    let a1 = scalars[s_base + 1u]; let b1 = mask[m_base + 1u];
    let a2 = scalars[s_base + 2u]; let b2 = mask[m_base + 2u];
    let a3 = scalars[s_base + 3u]; let b3 = mask[m_base + 3u];
    let a4 = scalars[s_base + 4u]; let b4 = mask[m_base + 4u];
    let a5 = scalars[s_base + 5u]; let b5 = mask[m_base + 5u];
    let a6 = scalars[s_base + 6u]; let b6 = mask[m_base + 6u];
    let a7 = scalars[s_base + 7u]; let b7 = mask[m_base + 7u];

    // s = a + b. a, b < r < 2^254 => s < 2^255, so the add never carries out of
    // the 8th word; the 9th-limb carry is provably 0 and is not tracked.
    var s: array<u32, 8>;
    var carry: u32 = 0u;
    { let lo = a0 + b0; let v = lo + carry; s[0] = v; carry = select(0u,1u, lo < a0) + select(0u,1u, v < lo); }
    { let lo = a1 + b1; let v = lo + carry; s[1] = v; carry = select(0u,1u, lo < a1) + select(0u,1u, v < lo); }
    { let lo = a2 + b2; let v = lo + carry; s[2] = v; carry = select(0u,1u, lo < a2) + select(0u,1u, v < lo); }
    { let lo = a3 + b3; let v = lo + carry; s[3] = v; carry = select(0u,1u, lo < a3) + select(0u,1u, v < lo); }
    { let lo = a4 + b4; let v = lo + carry; s[4] = v; carry = select(0u,1u, lo < a4) + select(0u,1u, v < lo); }
    { let lo = a5 + b5; let v = lo + carry; s[5] = v; carry = select(0u,1u, lo < a5) + select(0u,1u, v < lo); }
    { let lo = a6 + b6; let v = lo + carry; s[6] = v; carry = select(0u,1u, lo < a6) + select(0u,1u, v < lo); }
    { let lo = a7 + b7; let v = lo + carry; s[7] = v; carry = select(0u,1u, lo < a7) + select(0u,1u, v < lo); }

    // d = s - r (borrow chain). borrow == 0 after the last word iff s >= r.
    var d: array<u32, 8>;
    var borrow: u32 = 0u;
    { let t = s[0] - R8_0; let v = t - borrow; d[0] = v; borrow = select(0u,1u, s[0] < R8_0) + select(0u,1u, t < borrow); }
    { let t = s[1] - R8_1; let v = t - borrow; d[1] = v; borrow = select(0u,1u, s[1] < R8_1) + select(0u,1u, t < borrow); }
    { let t = s[2] - R8_2; let v = t - borrow; d[2] = v; borrow = select(0u,1u, s[2] < R8_2) + select(0u,1u, t < borrow); }
    { let t = s[3] - R8_3; let v = t - borrow; d[3] = v; borrow = select(0u,1u, s[3] < R8_3) + select(0u,1u, t < borrow); }
    { let t = s[4] - R8_4; let v = t - borrow; d[4] = v; borrow = select(0u,1u, s[4] < R8_4) + select(0u,1u, t < borrow); }
    { let t = s[5] - R8_5; let v = t - borrow; d[5] = v; borrow = select(0u,1u, s[5] < R8_5) + select(0u,1u, t < borrow); }
    { let t = s[6] - R8_6; let v = t - borrow; d[6] = v; borrow = select(0u,1u, s[6] < R8_6) + select(0u,1u, t < borrow); }
    { let t = s[7] - R8_7; let v = t - borrow; d[7] = v; borrow = select(0u,1u, s[7] < R8_7) + select(0u,1u, t < borrow); }

    // borrow != 0  => s < r  => keep s (no reduction); else use d = s - r.
    let keep_s = borrow != 0u;
    scalars[s_base + 0u] = select(d[0], s[0], keep_s);
    scalars[s_base + 1u] = select(d[1], s[1], keep_s);
    scalars[s_base + 2u] = select(d[2], s[2], keep_s);
    scalars[s_base + 3u] = select(d[3], s[3], keep_s);
    scalars[s_base + 4u] = select(d[4], s[4], keep_s);
    scalars[s_base + 5u] = select(d[5], s[5], keep_s);
    scalars[s_base + 6u] = select(d[6], s[6], keep_s);
    scalars[s_base + 7u] = select(d[7], s[7], keep_s);

    {{{ recompile }}}
}
`;

export const transpose_count_tiled = `// Parallel transpose — Phase 1 of 4: per-point-tile bucket histogram.
//
// Tiled counting-sort count. Dispatch (num_point_tiles, num_windows):
// workgroup (point_tile, window) histograms its tile's column indices into
// a workgroup-shared histogram and writes the tile's partial-histogram row
// to \`partials\`. Parallelizing across point-tiles (not just windows) keeps
// the GPU saturated so DRAM latency is hidden; with one tile holding
// ~BW digits over BW buckets the shared-atomic contention is ~1-deep. No
// global atomics are used — only on-chip shared atomics.
//
// partials layout: [window][point_tile][bucket], row stride num_point_tiles*BW;
//   partials[(window*num_point_tiles + point_tile)*BW + bucket] = count of
//   \`bucket\` among this window's points in this tile.
//
// If BW exceeds the shared histogram capacity TILE, buckets are covered in
// ceil(BW/TILE) sub-tiles, each re-scanning the (coalesced) point tile.

const WG: u32 = {{ workgroup_size }}u;
const TILE: u32 = {{ tile }}u;          // shared histogram capacity (entries)

// One u32 per (window, point): low 31 bits = bucket index (Booth digit),
// bit 31 = sign. We mask off the sign bit when using the entry as a CSR
// column index. See decompose_scalars_booth header for the packing rationale.
@group(0) @binding(0)
var<storage, read> bucket_and_sign: array<u32>;

@group(0) @binding(1)
var<storage, read_write> partials: array<u32>;

@group(0) @binding(2)
var<uniform> params: vec4<u32>;
// params[0] = num_point_tiles  params[1] = BW  params[2] = n  params[3] = points_per_tile

var<workgroup> hist: array<atomic<u32>, {{ tile }}>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let point_tile = wid.x;
    let window = wid.y;

    let num_point_tiles = params[0];
    let n_cols = params[1];
    let n = params[2];
    let points_per_tile = params[3];

    let cci_offset = window * n;
    let part_offset = (window * num_point_tiles + point_tile) * n_cols;
    let tile_point_lo = point_tile * points_per_tile;
    var tile_point_hi = tile_point_lo + points_per_tile;
    if (tile_point_hi > n) { tile_point_hi = n; }

    // Sub-tile loop: shared histogram has fixed capacity TILE entries, so if
    // the bucket count BW exceeds TILE, cover BW in ceil(BW/TILE) sub-tiles,
    // re-scanning the point tile per sub-tile. Naming: \`bucket_subtile_*\` is
    // a window of bucket indices [bucket_subtile_lo, bucket_subtile_hi) that
    // fits in the shared hist.
    let num_bucket_subtiles = (n_cols + TILE - 1u) / TILE;
    for (var t: u32 = 0u; t < num_bucket_subtiles; t = t + 1u) {
        let bucket_subtile_lo = t * TILE;
        let bucket_subtile_hi = bucket_subtile_lo + TILE;

        // Zero this sub-tile's shared histogram.
        for (var s: u32 = tid; s < TILE; s = s + WG) {
            atomicStore(&hist[s], 0u);
        }
        workgroupBarrier();

        // Tally every column index in this point tile that falls in this
        // bucket sub-tile. Mask off bit 31 (sign) — only the bucket index
        // matters here.
        for (var i: u32 = tile_point_lo + tid; i < tile_point_hi; i = i + WG) {
            let col = bucket_and_sign[cci_offset + i] & 0x7FFFFFFFu;
            if (col >= bucket_subtile_lo && col < bucket_subtile_hi) {
                atomicAdd(&hist[col - bucket_subtile_lo], 1u);
            }
        }
        workgroupBarrier();

        // Store this sub-tile's counts to the point tile's partial row (one
        // writer per cell — plain store, no atomic).
        for (var s: u32 = tid; s < TILE; s = s + WG) {
            let col = bucket_subtile_lo + s;
            if (col < n_cols) {
                partials[part_offset + col] = atomicLoad(&hist[s]);
            }
        }
        workgroupBarrier();
    }

    {{{ recompile }}}
}
`;

export const transpose_parallel_scan = `// Parallel transpose — Phase 2 of 3: in-place inclusive prefix sum
// (scan) of per-column counts → per-column start offsets.
//
// One *workgroup* per subtask, 256 threads per workgroup, each thread
// handles ceil((n_cols + 1) / 256) elements. Standard three-phase
// chunked scan:
//
//   A. Each thread sums its chunk into a local register; thread sums go
//      into workgroup-shared memory.
//   B. Workgroup-level inclusive scan over the 256 thread sums via
//      Hillis–Steele (O(N log N) work but log N depth — fine at N=256).
//      Convert to exclusive prefix per thread.
//   C. Each thread re-reads its chunk and writes inclusive prefix-sum
//      values starting from its block prefix.
//
// Replaces the previous serial-per-subtask scan that measured 37 ms of
// GPU time at N=2^16 (the new dominant cost after the parallel
// count/scatter dispatches dropped to <0.5 ms each). Expected to drop
// to ~1-2 ms with full workgroup parallelism.
//
// Bit-equivalent output to the serial scan in transpose_serial.wgsl
// lines 58-61: csc_col_ptr[k] = sum_{j=0}^{k-1} count(j) for k in [0, n].
// (Inclusive scan over the array where csc_col_ptr[0] = 0 and
// csc_col_ptr[i] = count(i-1) for i >= 1.)

const SCAN_WG_SIZE = 256u;

@group(0) @binding(0)
var<storage, read_write> all_csc_col_ptr: array<atomic<u32>>;

@group(0) @binding(1)
var<uniform> params: vec3<u32>;

var<workgroup> wg_sums: array<u32, SCAN_WG_SIZE>;

@compute
@workgroup_size(SCAN_WG_SIZE)
fn main(
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let tid = lid.x;
    let subtask_idx = wid.x;

    let n = params[1];
    let n_plus_1 = n + 1u;
    let base = subtask_idx * n_plus_1;

    let chunk_size = (n_plus_1 + SCAN_WG_SIZE - 1u) / SCAN_WG_SIZE;
    let chunk_start = tid * chunk_size;
    var chunk_end = chunk_start + chunk_size;
    if (chunk_end > n_plus_1) {
        chunk_end = n_plus_1;
    }

    // Phase A: compute this thread's chunk-local sum.
    var local_sum: u32 = 0u;
    for (var i = chunk_start; i < chunk_end; i = i + 1u) {
        local_sum = local_sum + atomicLoad(&all_csc_col_ptr[base + i]);
    }
    wg_sums[tid] = local_sum;
    workgroupBarrier();

    // Phase B: Hillis–Steele inclusive scan over wg_sums.
    for (var stride = 1u; stride < SCAN_WG_SIZE; stride = stride * 2u) {
        var x = wg_sums[tid];
        if (tid >= stride) {
            x = x + wg_sums[tid - stride];
        }
        workgroupBarrier();
        wg_sums[tid] = x;
        workgroupBarrier();
    }
    // After the loop, wg_sums[tid] = inclusive scan up through tid.
    // The exclusive prefix is wg_sums[tid] - local_sum.
    let block_prefix = wg_sums[tid] - local_sum;

    // Phase C: in-place inclusive prefix scan over this thread's chunk,
    // starting from block_prefix. The serial version did exactly the
    // same in-place inclusive write; the only race-free constraint is
    // that distinct threads operate on disjoint chunks, which holds by
    // construction here.
    var running = block_prefix;
    for (var i = chunk_start; i < chunk_end; i = i + 1u) {
        running = running + atomicLoad(&all_csc_col_ptr[base + i]);
        atomicStore(&all_csc_col_ptr[base + i], running);
    }

    {{{ recompile }}}
}
`;

export const transpose_reduce_tiled = `// Parallel transpose — Phase 2 of 4: reduce per-point-tile partials over
// the point-tile axis.
//
// Dispatch (ceil(BW/WG), num_windows): each thread owns one bucket. It
//   (a) sums the bucket's per-tile counts into the window's column count,
//       written to all_csc_col_ptr[window*(BW+1) + bucket + 1], and
//   (b) rewrites partials[window][point_tile][bucket] in place with the
//       point-tile-exclusive prefix sum
//       Sum_{pt<point_tile} partials0[window][pt][bucket].
//
// Each thread owns a disjoint bucket column of \`partials\`, so the in-place
// rewrite needs no atomics and has no races. Slot 0 of every window's
// all_csc_col_ptr row is left at 0 (zeroed by the host before this pass);
// Phase 3 (the scan) turns the per-column counts into inclusive offsets.

const WG: u32 = {{ workgroup_size }}u;

@group(0) @binding(0)
var<storage, read_write> partials: array<u32>;

@group(0) @binding(1)
var<storage, read_write> all_csc_col_ptr: array<u32>;

@group(0) @binding(2)
var<uniform> params: vec4<u32>;
// params[0] = num_point_tiles  params[1] = BW

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let num_point_tiles = params[0];
    let n_cols = params[1];
    let bucket = gid.x;
    let window = wid.y;
    if (bucket >= n_cols) { return; }

    let win_part = window * num_point_tiles * n_cols;
    var run: u32 = 0u;
    for (var k: u32 = 0u; k < num_point_tiles; k = k + 1u) {
        let idx = win_part + k * n_cols + bucket;
        let t = partials[idx];
        partials[idx] = run;          // point-tile-exclusive prefix
        run = run + t;
    }
    // \`run\` is now the bucket's total count across the whole window.
    all_csc_col_ptr[window * (n_cols + 1u) + bucket + 1u] = run;

    {{{ recompile }}}
}
`;

export const transpose_scatter_tiled = `// Parallel transpose — Phase 4 of 4: scatter point indices into CSC slots.
//
// Tiled counting-sort scatter. Dispatch (num_point_tiles, num_windows):
// workgroup (point_tile, window) re-scans its point tile and places each
// point index into all_csc_val_idxs. The within-tile write cursor lives in
// workgroup-shared memory (shared atomics only — no global atomics); one
// tile holds ~BW digits over BW buckets so contention is ~1-deep.
//
// Tile (point_tile, window)'s bucket-b points are written starting at
//   all_csc_col_ptr[window*(BW+1) + b]                — global bucket start
//   + partials[(window*num_point_tiles+point_tile)*BW + b]  — tile-excl prefix
// and the shared cursor curr[] supplies the within-tile slot. Each
// all_csc_val_idxs slot is written exactly once.
//
// If BW exceeds the shared cursor capacity TILE, buckets are covered in
// ceil(BW/TILE) sub-tiles, each re-scanning the point tile.

const WG: u32 = {{ workgroup_size }}u;
const TILE: u32 = {{ tile }}u;          // shared cursor capacity (entries)

// One u32 per (window, point): low 31 bits = bucket index, bit 31 = sign.
// We mask off the sign bit when scattering by bucket. See
// decompose_scalars_booth header for the packing rationale.
@group(0) @binding(0)
var<storage, read> bucket_and_sign: array<u32>;

@group(0) @binding(1)
var<storage, read> all_csc_col_ptr: array<u32>;

@group(0) @binding(2)
var<storage, read> partials: array<u32>;

@group(0) @binding(3)
var<storage, read_write> all_csc_val_idxs: array<u32>;

@group(0) @binding(4)
var<uniform> params: vec4<u32>;
// params[0] = num_point_tiles  params[1] = BW  params[2] = n  params[3] = points_per_tile

var<workgroup> curr: array<atomic<u32>, {{ tile }}>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(local_invocation_id) lid: vec3<u32>,
        @builtin(workgroup_id) wid: vec3<u32>) {
    let tid = lid.x;
    let point_tile = wid.x;
    let window = wid.y;

    let num_point_tiles = params[0];
    let n_cols = params[1];
    let n = params[2];
    let points_per_tile = params[3];

    let cci_offset = window * n;
    let ccp_offset = window * (n_cols + 1u);
    let part_offset = (window * num_point_tiles + point_tile) * n_cols;
    let tile_point_lo = point_tile * points_per_tile;
    var tile_point_hi = tile_point_lo + points_per_tile;
    if (tile_point_hi > n) { tile_point_hi = n; }

    // Sub-tile loop over buckets: shared \`curr\` cursor has fixed capacity
    // TILE entries, so for large BW we cover BW in ceil(BW/TILE) sub-tiles,
    // re-scanning the point tile per sub-tile.
    let num_bucket_subtiles = (n_cols + TILE - 1u) / TILE;
    for (var t: u32 = 0u; t < num_bucket_subtiles; t = t + 1u) {
        let bucket_subtile_lo = t * TILE;
        let bucket_subtile_hi = bucket_subtile_lo + TILE;

        // Zero this sub-tile's shared within-tile write cursors.
        for (var s: u32 = tid; s < TILE; s = s + WG) {
            atomicStore(&curr[s], 0u);
        }
        workgroupBarrier();

        // Place every point in this point tile whose column falls in this
        // bucket sub-tile. Mask off bit 31 (sign) — only the bucket index
        // addresses the CSC.
        for (var i: u32 = tile_point_lo + tid; i < tile_point_hi; i = i + WG) {
            let col = bucket_and_sign[cci_offset + i] & 0x7FFFFFFFu;
            if (col >= bucket_subtile_lo && col < bucket_subtile_hi) {
                let local_slot = atomicAdd(&curr[col - bucket_subtile_lo], 1u);
                let base = all_csc_col_ptr[ccp_offset + col] + partials[part_offset + col];
                all_csc_val_idxs[cci_offset + base + local_slot] = i;
            }
        }
        workgroupBarrier();
    }

    {{{ recompile }}}
}
`;

export const by_inverse_loop = `// ============================================================================
// Option "loop": register-minimal Bernstein-Yang safegcd field inverse.
//
// Drop-in alternative to \`fr_inv_by_a\`. Same signature / contract:
//   fr_inv_by_loop(a: BigInt) -> BigInt  — Montgomery-form inverse of \`a\`.
//
// This is \`by_inverse_a\`'s algorithm — BATCH=26, NUM_OUTER=29, the identical
// divstep sequence and k*p trick — with apply_matrix rewritten from a fully
// unrolled flat expression (~150-230 live i32 locals, the inverse's register
// peak) into a ROLLING LOOP (~20-25 live values). Same arithmetic, an order
// of magnitude fewer registers.
//
// The rolling apply_matrix is a faithful transliteration of \`applyMatrix\` in
// the tested TS reference \`src/msm_webgpu/cuzk/bernstein_yang_a.ts\`:
//   - BATCH=26 = 2*WORD_SIZE, so >>26 is a clean two-limb drop:
//     out[j] = product-limb[j+2]. No bit-recombination.
//   - Each matrix entry splits m = m_lo + m_hi*2^13; base-2^13 product limb i
//     reads input limbs i and i-1, so the loop carries a one-limb input
//     window (fp/gp) plus the running carry.
//   - In place: the loop writes out[i-2] only after reading in[i], so the
//     write trails the read by two limbs — no input snapshot needed.
//
// All identifiers are namespaced byl_/BYL_ so this coexists with by_inverse_a.
// Relies on the same external helpers: montgomery_product, get_p,
// get_r_cubed, bigint_is_neg_2c, bigint_gte, the u64_* helpers (bigint_by),
// the constants MASK / WORD_SIZE, and context vars num_words / p_inv_by_a_lo.
//
// NOTE: never write Mustache tags inside these comments — Mustache renders
// them regardless of WGSL comment syntax and a partial tag would inline a
// whole partial mid-comment.
// ============================================================================

// Bernstein-Yang divstep bound for a 256-bit modulus is 735 divsteps.
// BATCH=26 -> NUM_OUTER = ceil(735/26) = 29.
const BYL_BATCH: u32 = 26u;
const BYL_NUM_OUTER: u32 = 29u;
const BYL_REDUCE_INTERVAL: u32 = 4u;
const BYL_RTC_MAX_ITERS: u32 = 4u;

// Low BATCH=26 bits — used by the k*p modular-cancellation trick.
const BYL_MASK_BATCH: u32 = (1u << 26u) - 1u;
// p^(-1) mod 2^26 (Hensel-lifted), the same value by_inverse_a consumes.
const BYL_P_INV_LO: u32 = {{ p_inv_by_a_lo }}u;

// 2x2 transition matrix from BYL_BATCH divsteps. After 26 divsteps every
// entry satisfies |u,v,q,r| <= 2^26, so a plain i32 holds it.
struct BylMat {
    u: i32,
    v: i32,
    q: i32,
    r: i32,
}

// ============================================================================
// byl_divsteps: BYL_BATCH branchy divsteps on the low 64 bits of (f, g),
// carried as a vec2<u32>. We need >= BATCH bits to drive the decisions; 64
// leaves 38 bits of sign-propagation headroom. Transliteration of
// \`bya_divsteps\` / the TS \`divsteps\`.
// ============================================================================
fn byl_divsteps(delta: ptr<function, i32>, f_lo_in: vec2<u32>, g_lo_in: vec2<u32>) -> BylMat {
    var f_lo: vec2<u32> = f_lo_in;
    var g_lo: vec2<u32> = g_lo_in;
    var u: i32 = 1;
    var v: i32 = 0;
    var q: i32 = 0;
    var r: i32 = 1;
    var d: i32 = *delta;
    // Branchless divsteps: the three cases (swap / add / shift) are folded
    // into per-variable \`select\`s so every lane runs identical control flow.
    // A wide-wave GPU otherwise serialises all three case-bodies on any wave
    // whose lanes land in different cases. Every \`new_*\` is formed from the
    // pre-iteration f/g/u/v/q/r/d, then the seven are committed together.
    for (var i: u32 = 0u; i < BYL_BATCH; i = i + 1u) {
        let g_odd: bool = u64_low_bit(g_lo) != 0u;
        let swap: bool = g_odd && (d > 0);
        let addc: bool = g_odd && (d <= 0);

        // u64_sub / u64_add wrap on the low 64 bits; computing both
        // unconditionally is harmless — the unused one is just discarded.
        let g_minus_f: vec2<u32> = u64_sub(g_lo, f_lo);
        let g_plus_f: vec2<u32> = u64_add(g_lo, f_lo);
        let g_pre: vec2<u32> = select(select(g_lo, g_plus_f, addc), g_minus_f, swap);

        let new_f: vec2<u32> = select(f_lo, g_lo, swap);
        let new_g: vec2<u32> = u64_shr1(g_pre);
        let new_u: i32 = select(u << 1u, q << 1u, swap);
        let new_v: i32 = select(v << 1u, r << 1u, swap);
        let new_q: i32 = select(select(q, q + u, addc), q - u, swap);
        let new_r: i32 = select(select(r, r + v, addc), r - v, swap);
        let new_d: i32 = select(d + 1, 1 - d, swap);

        f_lo = new_f;
        g_lo = new_g;
        u = new_u;
        v = new_v;
        q = new_q;
        r = new_r;
        d = new_d;
    }
    *delta = d;
    return BylMat(u, v, q, r);
}

// ============================================================================
// byl_low_u64: low 64 bits of a 20 x 13-bit BigInt with canonical 13-bit
// limbs (the apply_matrix output guarantees limbs 0..18 are canonical).
// ============================================================================
fn byl_low_u64(x: ptr<function, BigInt>) -> vec2<u32> {
    let l0: u32 = (*x).limbs[0] & MASK;
    let l1: u32 = (*x).limbs[1] & MASK;
    let l2: u32 = (*x).limbs[2] & MASK;
    let l3: u32 = (*x).limbs[3] & MASK;
    let l4: u32 = (*x).limbs[4] & MASK;
    let lo32: u32 = l0 | (l1 << 13u) | (l2 << 26u);
    let hi32: u32 = (l2 >> 6u) | (l3 << 7u) | (l4 << 20u);
    return vec2<u32>(lo32, hi32);
}

// ============================================================================
// byl_normalise: carry-propagate so every limb in [0, NUM_WORDS-1) is a
// canonical 13-bit value and the top limb absorbs the signed extension.
// ============================================================================
fn byl_normalise(x: ptr<function, BigInt>) {
    var c: i32 = 0;
    for (var i: u32 = 0u; i < {{ num_words }}u - 1u; i = i + 1u) {
        let v: i32 = i32((*x).limbs[i]) + c;
        (*x).limbs[i] = u32(v) & MASK;
        c = v >> WORD_SIZE;
    }
    (*x).limbs[{{ num_words }}u - 1u] =
        u32(i32((*x).limbs[{{ num_words }}u - 1u]) + c) & MASK;
}

// ============================================================================
// byl_apply_matrix_fg: (f, g) <- ((u*f + v*g) >> 26, (q*f + r*g) >> 26).
//
// Rolling lookahead loop, in place. Iteration i forms the base-2^13 product
// limb i of each row from input limbs i and i-1 (fp/gp hold the i-1 window),
// propagates the carry, and stores out[i-2] = product-limb[i] (the >>26 drop).
// The two top product limbs are emitted after the loop.
// ============================================================================
fn byl_apply_matrix_fg(m: BylMat, f: ptr<function, BigInt>, g: ptr<function, BigInt>) {
    let top: u32 = {{ num_words }}u - 1u;
    let sign_shift: u32 = 32u - WORD_SIZE;

    let u_lo: i32 = i32(u32(m.u) & MASK);
    let u_hi: i32 = m.u >> WORD_SIZE;
    let v_lo: i32 = i32(u32(m.v) & MASK);
    let v_hi: i32 = m.v >> WORD_SIZE;
    let q_lo: i32 = i32(u32(m.q) & MASK);
    let q_hi: i32 = m.q >> WORD_SIZE;
    let r_lo: i32 = i32(u32(m.r) & MASK);
    let r_hi: i32 = m.r >> WORD_SIZE;

    var cf: i32 = 0;
    var cg: i32 = 0;
    var fp: i32 = 0;
    var gp: i32 = 0;
    for (var i: u32 = 0u; i < {{ num_words }}u; i = i + 1u) {
        // Top limb carries the signed extension of the whole integer;
        // lower limbs are canonical [0, 2^13).
        var fi: i32;
        var gi: i32;
        if (i == top) {
            fi = (i32((*f).limbs[i]) << sign_shift) >> sign_shift;
            gi = (i32((*g).limbs[i]) << sign_shift) >> sign_shift;
        } else {
            fi = i32((*f).limbs[i]);
            gi = i32((*g).limbs[i]);
        }
        let nf: i32 = u_lo * fi + v_lo * gi + u_hi * fp + v_hi * gp + cf;
        let ng: i32 = q_lo * fi + r_lo * gi + q_hi * fp + r_hi * gp + cg;
        cf = nf >> WORD_SIZE;
        cg = ng >> WORD_SIZE;
        if (i >= 2u) {
            (*f).limbs[i - 2u] = u32(nf) & MASK;
            (*g).limbs[i - 2u] = u32(ng) & MASK;
        }
        fp = fi;
        gp = gi;
    }
    // Two top product limbs: position 20 (= u_hi*f[19] + v_hi*g[19] + carry)
    // splits into output limbs top-1 and top.
    let nf_top: i32 = u_hi * fp + v_hi * gp + cf;
    let ng_top: i32 = q_hi * fp + r_hi * gp + cg;
    (*f).limbs[top - 1u] = u32(nf_top) & MASK;
    (*g).limbs[top - 1u] = u32(ng_top) & MASK;
    (*f).limbs[top] = u32(nf_top >> WORD_SIZE);
    (*g).limbs[top] = u32(ng_top >> WORD_SIZE);
}

// ============================================================================
// byl_apply_matrix_de: (d, e) <- ((u*d + v*e + k_d*p) >> 26,
//                                 (q*d + r*e + k_e*p) >> 26).
//
// k_d, k_e are chosen so the low 26 bits of each numerator cancel mod p
// (standard safegcd k*p trick). Product limbs 0 and 1 are then zero; the
// rolling loop starts at i=2 with cd/ce seeded to their carry-out.
// ============================================================================
fn byl_apply_matrix_de(
    m: BylMat,
    d: ptr<function, BigInt>,
    e: ptr<function, BigInt>,
    p: ptr<function, BigInt>,
) {
    let top: u32 = {{ num_words }}u - 1u;
    let sign_shift: u32 = 32u - WORD_SIZE;

    let u_lo: i32 = i32(u32(m.u) & MASK);
    let u_hi: i32 = m.u >> WORD_SIZE;
    let v_lo: i32 = i32(u32(m.v) & MASK);
    let v_hi: i32 = m.v >> WORD_SIZE;
    let q_lo: i32 = i32(u32(m.q) & MASK);
    let q_hi: i32 = m.q >> WORD_SIZE;
    let r_lo: i32 = i32(u32(m.r) & MASK);
    let r_hi: i32 = m.r >> WORD_SIZE;

    let d0: i32 = i32((*d).limbs[0]);
    let e0: i32 = i32((*e).limbs[0]);
    let d1: i32 = i32((*d).limbs[1]);
    let e1: i32 = i32((*e).limbs[1]);
    let p0: i32 = i32((*p).limbs[0]);
    let p1: i32 = i32((*p).limbs[1]);

    // Pre-k*p product limbs 0 and 1 of (u*d+v*e) and (q*d+r*e).
    let nd0: i32 = u_lo * d0 + v_lo * e0;
    let ne0: i32 = q_lo * d0 + r_lo * e0;
    let nd1: i32 = u_lo * d1 + v_lo * e1 + u_hi * d0 + v_hi * e0;
    let ne1: i32 = q_lo * d1 + r_lo * e1 + q_hi * d0 + r_hi * e0;

    // k = (-t) * p^-1 mod 2^26, where t = low 26 bits of the numerator.
    let nd0_low: u32 = u32(nd0) & MASK;
    let nd1_carry: u32 = u32(nd1 + (nd0 >> WORD_SIZE)) & MASK;
    let t_d: u32 = (nd0_low | (nd1_carry << WORD_SIZE)) & BYL_MASK_BATCH;
    let ne0_low: u32 = u32(ne0) & MASK;
    let ne1_carry: u32 = u32(ne1 + (ne0 >> WORD_SIZE)) & MASK;
    let t_e: u32 = (ne0_low | (ne1_carry << WORD_SIZE)) & BYL_MASK_BATCH;

    let neg_td: u32 = (~t_d + 1u) & BYL_MASK_BATCH;
    let neg_te: u32 = (~t_e + 1u) & BYL_MASK_BATCH;
    let k_d: u32 = (neg_td * BYL_P_INV_LO) & BYL_MASK_BATCH;
    let k_e: u32 = (neg_te * BYL_P_INV_LO) & BYL_MASK_BATCH;
    let kd_lo: i32 = i32(k_d & MASK);
    let kd_hi: i32 = i32(k_d >> WORD_SIZE);
    let ke_lo: i32 = i32(k_e & MASK);
    let ke_hi: i32 = i32(k_e >> WORD_SIZE);

    // Carry into product limb 2: product limbs 0 and 1 (with k*p folded in)
    // have zero low-13 bits; cd/ce are their carry-out.
    var cd: i32 = (nd1 + kd_lo * p1 + kd_hi * p0 + ((nd0 + kd_lo * p0) >> WORD_SIZE)) >> WORD_SIZE;
    var ce: i32 = (ne1 + ke_lo * p1 + ke_hi * p0 + ((ne0 + ke_lo * p0) >> WORD_SIZE)) >> WORD_SIZE;

    var dp: i32 = d1;
    var ep: i32 = e1;
    for (var i: u32 = 2u; i < {{ num_words }}u; i = i + 1u) {
        var di: i32;
        var ei: i32;
        if (i == top) {
            di = (i32((*d).limbs[i]) << sign_shift) >> sign_shift;
            ei = (i32((*e).limbs[i]) << sign_shift) >> sign_shift;
        } else {
            di = i32((*d).limbs[i]);
            ei = i32((*e).limbs[i]);
        }
        let pi: i32 = i32((*p).limbs[i]);
        let pim1: i32 = i32((*p).limbs[i - 1u]);
        let nd: i32 = u_lo * di + v_lo * ei + u_hi * dp + v_hi * ep + kd_lo * pi + kd_hi * pim1 + cd;
        let ne: i32 = q_lo * di + r_lo * ei + q_hi * dp + r_hi * ep + ke_lo * pi + ke_hi * pim1 + ce;
        cd = nd >> WORD_SIZE;
        ce = ne >> WORD_SIZE;
        (*d).limbs[i - 2u] = u32(nd) & MASK;
        (*e).limbs[i - 2u] = u32(ne) & MASK;
        dp = di;
        ep = ei;
    }
    let p_top: i32 = i32((*p).limbs[top]);
    let nd_top: i32 = u_hi * dp + v_hi * ep + kd_hi * p_top + cd;
    let ne_top: i32 = q_hi * dp + r_hi * ep + ke_hi * p_top + ce;
    (*d).limbs[top - 1u] = u32(nd_top) & MASK;
    (*e).limbs[top - 1u] = u32(ne_top) & MASK;
    (*d).limbs[top] = u32(nd_top >> WORD_SIZE);
    (*e).limbs[top] = u32(ne_top >> WORD_SIZE);
}

// ============================================================================
// Driver helpers — rolling loops.
// ============================================================================

fn byl_is_zero(x: ptr<function, BigInt>) -> bool {
    var a: u32 = 0u;
    for (var i: u32 = 0u; i < {{ num_words }}u; i = i + 1u) {
        a = a | (*x).limbs[i];
    }
    return a == 0u;
}

fn byl_neg_inplace(x: ptr<function, BigInt>) {
    for (var i: u32 = 0u; i < {{ num_words }}u; i = i + 1u) {
        (*x).limbs[i] = u32(-i32((*x).limbs[i]));
    }
    byl_normalise(x);
}

fn byl_add_p_inplace(x: ptr<function, BigInt>, p: ptr<function, BigInt>) {
    for (var i: u32 = 0u; i < {{ num_words }}u; i = i + 1u) {
        (*x).limbs[i] = u32(i32((*x).limbs[i]) + i32((*p).limbs[i]));
    }
    byl_normalise(x);
}

fn byl_sub_p_inplace(x: ptr<function, BigInt>, p: ptr<function, BigInt>) {
    for (var i: u32 = 0u; i < {{ num_words }}u; i = i + 1u) {
        (*x).limbs[i] = u32(i32((*x).limbs[i]) - i32((*p).limbs[i]));
    }
    byl_normalise(x);
}

fn byl_reduce_to_canonical(x: ptr<function, BigInt>, p: ptr<function, BigInt>) {
    byl_normalise(x);
    var done: bool = false;
    for (var it: u32 = 0u; it < BYL_RTC_MAX_ITERS; it = it + 1u) {
        if (done) { continue; }
        if (bigint_is_neg_2c(x)) {
            byl_add_p_inplace(x, p);
        } else if (bigint_gte(x, p)) {
            byl_sub_p_inplace(x, p);
        } else {
            done = true;
        }
    }
}

// ============================================================================
// fr_inv_by_loop: Bernstein-Yang safegcd inverse driver. BATCH=26,
// NUM_OUTER=29 — identical structure to fr_inv_by_a, register-minimal
// rolling apply_matrix. Returns the Montgomery-form inverse of \`a\`; assumes
// \`a\` nonzero (the caller / batch-inverse prefix product guarantees this).
// ============================================================================
fn fr_inv_by_loop(a: BigInt) -> BigInt {
    var p_loc: BigInt = get_p();
    var f: BigInt = get_p();
    var g: BigInt = a;

    var d: BigInt;
    var e: BigInt;
    for (var k: u32 = 0u; k < {{ num_words }}u; k = k + 1u) {
        d.limbs[k] = 0u;
        e.limbs[k] = 0u;
    }
    e.limbs[0] = 1u;

    var delta: i32 = 1;
    var done: bool = false;
    for (var iter: u32 = 0u; iter < BYL_NUM_OUTER; iter = iter + 1u) {
        if (done) { continue; }
        let f_lo: vec2<u32> = byl_low_u64(&f);
        let g_lo: vec2<u32> = byl_low_u64(&g);
        let m: BylMat = byl_divsteps(&delta, f_lo, g_lo);
        byl_apply_matrix_fg(m, &f, &g);
        byl_apply_matrix_de(m, &d, &e, &p_loc);
        if (((iter + 1u) % BYL_REDUCE_INTERVAL) == 0u) {
            byl_reduce_to_canonical(&d, &p_loc);
            byl_reduce_to_canonical(&e, &p_loc);
        }
        if (byl_is_zero(&g)) {
            done = true;
        }
    }

    byl_reduce_to_canonical(&d, &p_loc);
    if (bigint_is_neg_2c(&f)) {
        byl_neg_inplace(&d);
        byl_reduce_to_canonical(&d, &p_loc);
    }

    var inv_native: BigInt = d;
    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}

// ===========================================================================
// PACKED safegcd inverse (fr_inv_by_loop_pk). Same Bernstein-Yang algorithm
// and arithmetic as fr_inv_by_loop, but f,g,d,e,p are stored 2x13-bit limbs
// per u32 word (10 words instead of 20) -> HALF the per-thread private-memory
// footprint and half the apply_matrix memory traffic. Smaller footprint =>
// the GPU can keep more inverse threads resident => higher occupancy on the
// Adreno. All arithmetic stays i32/13-bit (no 64-bit emulation). Hand-derived
// from the validated rolling recurrence; word w holds limb 2w (bits 0..12)
// and limb 2w+1 (bits 13..25).
// ===========================================================================
struct Pk { w: array<u32, 10> }

fn pk_from_bigint(x: BigInt) -> Pk {
    var o: Pk;
    for (var k: u32 = 0u; k < 10u; k = k + 1u) {
        o.w[k] = (x.limbs[2u * k] & MASK) | ((x.limbs[2u * k + 1u] & MASK) << 13u);
    }
    return o;
}

fn pk_to_bigint(x: ptr<function, Pk>) -> BigInt {
    var o: BigInt;
    for (var k: u32 = 0u; k < 10u; k = k + 1u) {
        let word = (*x).w[k];
        o.limbs[2u * k] = word & MASK;
        o.limbs[2u * k + 1u] = (word >> 13u) & MASK;
    }
    return o;
}

fn pk_get_p() -> Pk { return pk_from_bigint(get_p()); }

// Packed modulus word w (limb 2w | limb(2w+1)<<13) as a compile-time
// immediate, from the module-scope P_i consts (montmul partial, always
// co-included). No per-thread modulus copy in scratch.
fn pk_p_word(w: u32) -> u32 {
    switch w {
        case 0u: { return P_LIMB_0 | (P_LIMB_1 << 13u); }
        case 1u: { return P_LIMB_2 | (P_LIMB_3 << 13u); }
        case 2u: { return P_LIMB_4 | (P_LIMB_5 << 13u); }
        case 3u: { return P_LIMB_6 | (P_LIMB_7 << 13u); }
        case 4u: { return P_LIMB_8 | (P_LIMB_9 << 13u); }
        case 5u: { return P_LIMB_10 | (P_LIMB_11 << 13u); }
        case 6u: { return P_LIMB_12 | (P_LIMB_13 << 13u); }
        case 7u: { return P_LIMB_14 | (P_LIMB_15 << 13u); }
        case 8u: { return P_LIMB_16 | (P_LIMB_17 << 13u); }
        default: { return P_LIMB_18 | (P_LIMB_19 << 13u); }
    }
}

// Low 64 bits from limbs 0..4 (words 0,1 and low limb of word 2).
fn pk_low_u64(x: ptr<function, Pk>) -> vec2<u32> {
    let w0 = (*x).w[0];
    let w1 = (*x).w[1];
    let l0: u32 = w0 & MASK;
    let l1: u32 = (w0 >> 13u) & MASK;
    let l2: u32 = w1 & MASK;
    let l3: u32 = (w1 >> 13u) & MASK;
    let l4: u32 = (*x).w[2] & MASK;
    let lo32: u32 = l0 | (l1 << 13u) | (l2 << 26u);
    let hi32: u32 = (l2 >> 6u) | (l3 << 7u) | (l4 << 20u);
    return vec2<u32>(lo32, hi32);
}

fn pk_is_zero(x: ptr<function, Pk>) -> bool {
    var a: u32 = 0u;
    for (var k: u32 = 0u; k < 10u; k = k + 1u) { a = a | (*x).w[k]; }
    return a == 0u;
}

// Sign bit of the 260-bit value = bit 12 of limb 19 = bit 25 of word 9.
fn pk_is_neg_2c(x: ptr<function, Pk>) -> bool { return (((*x).w[9] >> 25u) & 1u) == 1u; }

// Signed carry-propagate normalisation, 2 limbs/word; limb 19 (top) absorbs.
fn pk_normalise(x: ptr<function, Pk>) {
    var c: i32 = 0;
    for (var w: u32 = 0u; w < 10u; w = w + 1u) {
        let word = (*x).w[w];
        let lo: i32 = i32(word & MASK) + c;
        let olo: u32 = u32(lo) & MASK;
        c = lo >> 13u;
        let hi: i32 = i32((word >> 13u) & MASK) + c;
        let ohi: u32 = u32(hi) & MASK;
        if (w != 9u) { c = hi >> 13u; }
        (*x).w[w] = olo | (ohi << 13u);
    }
}

// out = x + p, carry-propagated (combines add + normalise). Top limb absorbs.
fn pk_add_p(x: ptr<function, Pk>) {
    var c: i32 = 0;
    for (var w: u32 = 0u; w < 10u; w = w + 1u) {
        let xw = (*x).w[w];
        let pw = pk_p_word(w);
        let lo: i32 = i32(xw & MASK) + i32(pw & MASK) + c;
        let olo: u32 = u32(lo) & MASK;
        c = lo >> 13u;
        let hi: i32 = i32((xw >> 13u) & MASK) + i32((pw >> 13u) & MASK) + c;
        let ohi: u32 = u32(hi) & MASK;
        if (w != 9u) { c = hi >> 13u; }
        (*x).w[w] = olo | (ohi << 13u);
    }
}

fn pk_sub_p(x: ptr<function, Pk>) {
    var c: i32 = 0;
    for (var w: u32 = 0u; w < 10u; w = w + 1u) {
        let xw = (*x).w[w];
        let pw = pk_p_word(w);
        let lo: i32 = i32(xw & MASK) - i32(pw & MASK) + c;
        let olo: u32 = u32(lo) & MASK;
        c = lo >> 13u;
        let hi: i32 = i32((xw >> 13u) & MASK) - i32((pw >> 13u) & MASK) + c;
        let ohi: u32 = u32(hi) & MASK;
        if (w != 9u) { c = hi >> 13u; }
        (*x).w[w] = olo | (ohi << 13u);
    }
}

fn pk_neg(x: ptr<function, Pk>) {
    var c: i32 = 0;
    for (var w: u32 = 0u; w < 10u; w = w + 1u) {
        let word = (*x).w[w];
        let lo: i32 = -i32(word & MASK) + c;
        let olo: u32 = u32(lo) & MASK;
        c = lo >> 13u;
        let hi: i32 = -i32((word >> 13u) & MASK) + c;
        let ohi: u32 = u32(hi) & MASK;
        if (w != 9u) { c = hi >> 13u; }
        (*x).w[w] = olo | (ohi << 13u);
    }
}

// x >= p ? (compare from limb 19 down).
fn pk_gte(x: ptr<function, Pk>) -> bool {
    for (var idx: u32 = 0u; idx < 10u; idx = idx + 1u) {
        let w = 9u - idx;
        let pw = pk_p_word(w);
        let xhi = ((*x).w[w] >> 13u) & MASK;
        let phi = (pw >> 13u) & MASK;
        if (xhi > phi) { return true; }
        if (xhi < phi) { return false; }
        let xlo = (*x).w[w] & MASK;
        let plo = pw & MASK;
        if (xlo > plo) { return true; }
        if (xlo < plo) { return false; }
    }
    return true;
}

fn pk_reduce_to_canonical(x: ptr<function, Pk>) {
    pk_normalise(x);
    var done: bool = false;
    for (var it: u32 = 0u; it < BYL_RTC_MAX_ITERS; it = it + 1u) {
        if (done) { continue; }
        if (pk_is_neg_2c(x)) { pk_add_p(x); }
        else if (pk_gte(x)) { pk_sub_p(x); }
        else { done = true; }
    }
}

// (f,g) <- ((u*f + v*g) >> 26, (q*f + r*g) >> 26). Rolling, 2 limbs/word.
fn pk_apply_matrix_fg(m: BylMat, f: ptr<function, Pk>, g: ptr<function, Pk>) {
    let u_lo: i32 = i32(u32(m.u) & MASK); let u_hi: i32 = m.u >> 13u;
    let v_lo: i32 = i32(u32(m.v) & MASK); let v_hi: i32 = m.v >> 13u;
    let q_lo: i32 = i32(u32(m.q) & MASK); let q_hi: i32 = m.q >> 13u;
    let r_lo: i32 = i32(u32(m.r) & MASK); let r_hi: i32 = m.r >> 13u;
    var cf: i32 = 0; var cg: i32 = 0; var fp: i32 = 0; var gp: i32 = 0;
    for (var w: u32 = 0u; w < 10u; w = w + 1u) {
        let fw = (*f).w[w]; let gw = (*g).w[w];
        let fe: i32 = i32(fw & MASK); let ge: i32 = i32(gw & MASK);
        let nfe: i32 = u_lo * fe + v_lo * ge + u_hi * fp + v_hi * gp + cf;
        let nge: i32 = q_lo * fe + r_lo * ge + q_hi * fp + r_hi * gp + cg;
        cf = nfe >> 13u; cg = nge >> 13u;
        var fo: i32; var go: i32;
        if (w == 9u) {
            fo = (i32((fw >> 13u) & MASK) << 19u) >> 19u;
            go = (i32((gw >> 13u) & MASK) << 19u) >> 19u;
        } else {
            fo = i32((fw >> 13u) & MASK); go = i32((gw >> 13u) & MASK);
        }
        let nfo: i32 = u_lo * fo + v_lo * go + u_hi * fe + v_hi * ge + cf;
        let ngo: i32 = q_lo * fo + r_lo * go + q_hi * fe + r_hi * ge + cg;
        cf = nfo >> 13u; cg = ngo >> 13u;
        if (w >= 1u) {
            (*f).w[w - 1u] = (u32(nfe) & MASK) | ((u32(nfo) & MASK) << 13u);
            (*g).w[w - 1u] = (u32(nge) & MASK) | ((u32(ngo) & MASK) << 13u);
        }
        fp = fo; gp = go;
    }
    let nft: i32 = u_hi * fp + v_hi * gp + cf;
    let ngt: i32 = q_hi * fp + r_hi * gp + cg;
    (*f).w[9] = (u32(nft) & MASK) | (u32(nft >> 13u) << 13u);
    (*g).w[9] = (u32(ngt) & MASK) | (u32(ngt >> 13u) << 13u);
}

// (d,e) <- ((u*d+v*e+k_d*p)>>26, (q*d+r*e+k_e*p)>>26). k*p cancels low 26 bits.
fn pk_apply_matrix_de(m: BylMat, d: ptr<function, Pk>, e: ptr<function, Pk>) {
    let u_lo: i32 = i32(u32(m.u) & MASK); let u_hi: i32 = m.u >> 13u;
    let v_lo: i32 = i32(u32(m.v) & MASK); let v_hi: i32 = m.v >> 13u;
    let q_lo: i32 = i32(u32(m.q) & MASK); let q_hi: i32 = m.q >> 13u;
    let r_lo: i32 = i32(u32(m.r) & MASK); let r_hi: i32 = m.r >> 13u;

    let dw0 = (*d).w[0]; let ew0 = (*e).w[0]; let pw0 = pk_p_word(0u);
    let d0: i32 = i32(dw0 & MASK); let d1: i32 = i32((dw0 >> 13u) & MASK);
    let e0: i32 = i32(ew0 & MASK); let e1: i32 = i32((ew0 >> 13u) & MASK);
    let p0: i32 = i32(pw0 & MASK); let p1: i32 = i32((pw0 >> 13u) & MASK);

    let nd0: i32 = u_lo * d0 + v_lo * e0; let ne0: i32 = q_lo * d0 + r_lo * e0;
    let nd1: i32 = u_lo * d1 + v_lo * e1 + u_hi * d0 + v_hi * e0;
    let ne1: i32 = q_lo * d1 + r_lo * e1 + q_hi * d0 + r_hi * e0;
    let nd0_low: u32 = u32(nd0) & MASK; let nd1_carry: u32 = u32(nd1 + (nd0 >> 13u)) & MASK;
    let t_d: u32 = (nd0_low | (nd1_carry << 13u)) & BYL_MASK_BATCH;
    let ne0_low: u32 = u32(ne0) & MASK; let ne1_carry: u32 = u32(ne1 + (ne0 >> 13u)) & MASK;
    let t_e: u32 = (ne0_low | (ne1_carry << 13u)) & BYL_MASK_BATCH;
    let k_d: u32 = (((~t_d + 1u) & BYL_MASK_BATCH) * BYL_P_INV_LO) & BYL_MASK_BATCH;
    let k_e: u32 = (((~t_e + 1u) & BYL_MASK_BATCH) * BYL_P_INV_LO) & BYL_MASK_BATCH;
    let kd_lo: i32 = i32(k_d & MASK); let kd_hi: i32 = i32(k_d >> 13u);
    let ke_lo: i32 = i32(k_e & MASK); let ke_hi: i32 = i32(k_e >> 13u);

    var cd: i32 = (nd1 + kd_lo * p1 + kd_hi * p0 + ((nd0 + kd_lo * p0) >> 13u)) >> 13u;
    var ce: i32 = (ne1 + ke_lo * p1 + ke_hi * p0 + ((ne0 + ke_lo * p0) >> 13u)) >> 13u;
    var dp: i32 = d1; var ep: i32 = e1;

    for (var w: u32 = 1u; w < 10u; w = w + 1u) {
        let dw = (*d).w[w]; let ew = (*e).w[w]; let pw = pk_p_word(w);
        // even limb i = 2w
        let di_e: i32 = i32(dw & MASK); let ei_e: i32 = i32(ew & MASK);
        let pi_e: i32 = i32(pw & MASK);
        let pim1_e: i32 = i32((pk_p_word(w - 1u) >> 13u) & MASK);
        let nd_e: i32 = u_lo * di_e + v_lo * ei_e + u_hi * dp + v_hi * ep + kd_lo * pi_e + kd_hi * pim1_e + cd;
        let ne_e: i32 = q_lo * di_e + r_lo * ei_e + q_hi * dp + r_hi * ep + ke_lo * pi_e + ke_hi * pim1_e + ce;
        cd = nd_e >> 13u; ce = ne_e >> 13u;
        // odd limb i = 2w+1
        var di_o: i32; var ei_o: i32;
        if (w == 9u) {
            di_o = (i32((dw >> 13u) & MASK) << 19u) >> 19u;
            ei_o = (i32((ew >> 13u) & MASK) << 19u) >> 19u;
        } else {
            di_o = i32((dw >> 13u) & MASK); ei_o = i32((ew >> 13u) & MASK);
        }
        let pi_o: i32 = i32((pw >> 13u) & MASK);
        let pim1_o: i32 = i32(pw & MASK);
        let nd_o: i32 = u_lo * di_o + v_lo * ei_o + u_hi * di_e + v_hi * ei_e + kd_lo * pi_o + kd_hi * pim1_o + cd;
        let ne_o: i32 = q_lo * di_o + r_lo * ei_o + q_hi * di_e + r_hi * ei_e + ke_lo * pi_o + ke_hi * pim1_o + ce;
        cd = nd_o >> 13u; ce = ne_o >> 13u;
        (*d).w[w - 1u] = (u32(nd_e) & MASK) | ((u32(nd_o) & MASK) << 13u);
        (*e).w[w - 1u] = (u32(ne_e) & MASK) | ((u32(ne_o) & MASK) << 13u);
        dp = di_o; ep = ei_o;
    }
    let p_top: i32 = i32((pk_p_word(9u) >> 13u) & MASK);
    let nd_top: i32 = u_hi * dp + v_hi * ep + kd_hi * p_top + cd;
    let ne_top: i32 = q_hi * dp + r_hi * ep + ke_hi * p_top + ce;
    (*d).w[9] = (u32(nd_top) & MASK) | (u32(nd_top >> 13u) << 13u);
    (*e).w[9] = (u32(ne_top) & MASK) | (u32(ne_top >> 13u) << 13u);
}

fn fr_inv_by_loop_pk(a: BigInt) -> BigInt {
    var f: Pk = pk_get_p();
    var g: Pk = pk_from_bigint(a);
    var d: Pk;
    var e: Pk; e.w[0] = 1u;
    var delta: i32 = 1;
    var done: bool = false;
    for (var iter: u32 = 0u; iter < BYL_NUM_OUTER; iter = iter + 1u) {
        if (done) { continue; }
        let f_lo: vec2<u32> = pk_low_u64(&f);
        let g_lo: vec2<u32> = pk_low_u64(&g);
        let m: BylMat = byl_divsteps(&delta, f_lo, g_lo);
        pk_apply_matrix_fg(m, &f, &g);
        pk_apply_matrix_de(m, &d, &e);
        if (((iter + 1u) % BYL_REDUCE_INTERVAL) == 0u) {
            pk_reduce_to_canonical(&d);
            pk_reduce_to_canonical(&e);
        }
        if (pk_is_zero(&g)) { done = true; }
    }
    pk_reduce_to_canonical(&d);
    if (pk_is_neg_2c(&f)) { pk_neg(&d); pk_reduce_to_canonical(&d); }
    var dd: BigInt = pk_to_bigint(&d);
    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&dd, &r_cubed);
}
`;

export const field = `fn fr_add(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigInt { 
    var res: BigInt;
    bigint_add(a, b, &res);
    return fr_reduce(&res);
}

fn fr_reduce(a: ptr<function, BigInt>) -> BigInt {
    var res: BigInt;
    var p: BigInt = get_p();
    var underflow = bigint_sub(a, &p, &res);
    if (underflow == 1u) {
        return *a;
    }

    return res;
}

fn fr_sub(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigInt {
    // (a - b) mod p, branch-free, in two limb-passes. a, b in [0, p).
    // bigint_sub yields a - b directly in [0, p) when a >= b (borrow 0).
    // When a < b it wraps to a - b + 2^260 and returns borrow 1; the
    // canonical result is then a - b + p in (0, p), so p is added back —
    // masked by the borrow and folded into a single add pass. That add's
    // carry-out is the discarded 2^260 wrap term. The select keeps it
    // branch-free; a == b gives res 0, borrow 0, no correction.
    var res: BigInt;
    let borrow = bigint_sub(a, b, &res);
    var p: BigInt = get_p();
    var out: BigInt;
    var carry: u32 = 0u;
    for (var j: u32 = 0u; j < NUM_WORDS; j = j + 1u) {
        let pj = select(0u, p.limbs[j], borrow == 1u);
        let c = res.limbs[j] + pj + carry;
        out.limbs[j] = c & MASK;
        carry = c >> WORD_SIZE;
    }
    return out;
}
`;

export const field8 = `// === Lever 2: 8x u32 live field representation ===
// Shared by the accumulate (ba_fused_super) and reduction (ba_reduce_level)
// kernels. Field elements live as \`array<u32, 8>\` — the canonical 256-bit
// packed form, which is ALSO the storage form, so loads/stores are plain
// 8-word copies. Live values cost 8 registers each instead of the
// 20x13-limb form's 20. Only the multiply needs 13-bit limbs:
// montgomery_product_f8 expands its operands to the 20x13 BigInt form,
// multiplies, contracts back. fr_add / fr_sub run natively on 8x u32.
//
// Resolved across the assembled shader: montgomery_product,
// unpack256_to_limbs, pack_limbs_to_256, and (addsub=unpack only)
// fr_add / fr_sub. Include this partial after dec_unpack / dec_pack.

// p as eight 32-bit words, for the native fr_add_f8 / fr_sub_f8.
{{#p8_consts}}
const P8_{{idx}}: u32 = {{val}}u;
{{/p8_consts}}

// R mod p (Montgomery one) as 8x u32 — the montgomery_product identity.
fn get_r_f8() -> array<u32, 8> {
    return array<u32, 8>({{ r8_csv }});
}

// get_r in the 20x13-limb form. Only \`fr_pow\` references it — a dead-code
// path in these kernels (fr_pow_funcs is pulled in for get_r_cubed, which
// the pk inverse needs). Derived from the get_r_f8 constant, so it is
// itself compile-time constant — no per-thread \`var\` materialisation.
fn get_r() -> BigInt {
    return unpack256_to_limbs(get_r_f8());
}

// is_zero on the 8x u32 form.
fn is_zero_f8(v: array<u32, 8>) -> bool {
    return (v[0] | v[1] | v[2] | v[3] | v[4] | v[5] | v[6] | v[7]) == 0u;
}

// montgomery_product on the 8x u32 form: expand both operands to the
// 20x13-limb arithmetic form, run the grouped Karatsuba multiply,
// contract the result back to 8x u32.
fn montgomery_product_f8(x: array<u32, 8>, y: array<u32, 8>) -> array<u32, 8> {
    var x20: BigInt = unpack256_to_limbs(x);
    var y20: BigInt = unpack256_to_limbs(y);
    var r: BigInt = montgomery_product(&x20, &y20);
    return pack_limbs_to_256(&r);
}

{{#addsub_unpack}}
// fr_add / fr_sub via expand -> 20x13 op -> contract. The A/B alternative
// to the native path; selected by \`addsub=unpack\`.
fn fr_add_f8(a: array<u32, 8>, b: array<u32, 8>) -> array<u32, 8> {
    var a20: BigInt = unpack256_to_limbs(a);
    var b20: BigInt = unpack256_to_limbs(b);
    var r: BigInt = fr_add(&a20, &b20);
    return pack_limbs_to_256(&r);
}

fn fr_sub_f8(a: array<u32, 8>, b: array<u32, 8>) -> array<u32, 8> {
    var a20: BigInt = unpack256_to_limbs(a);
    var b20: BigInt = unpack256_to_limbs(b);
    var r: BigInt = fr_sub(&a20, &b20);
    return pack_limbs_to_256(&r);
}
{{/addsub_unpack}}
{{^addsub_unpack}}
// Native 8x u32 fr_add / fr_sub — 8-word modular add / sub. WGSL has no
// add-with-carry, so the carry out of each word is \`u32(sum < operand)\`
// (one compare, no branch). a, b are canonical in [0, p).
fn fr_add_f8(a: array<u32, 8>, b: array<u32, 8>) -> array<u32, 8> {
    var s: array<u32, 8>;
    var carry: u32 = 0u;
{{#f8_words}}
    {
        let lo: u32 = a[{{i}}] + b[{{i}}];
        let v: u32 = lo + carry;
        s[{{i}}] = v;
        carry = select(0u, 1u, lo < a[{{i}}]) + select(0u, 1u, v < lo);
    }
{{/f8_words}}
    // s = a + b in [0, 2p); subtract p iff s >= p — the s - p borrow
    // chain underflows exactly when s < p.
    var d: array<u32, 8>;
    var borrow: u32 = 0u;
{{#f8_words}}
    {
        let t1: u32 = s[{{i}}] - P8_{{i}};
        let v: u32 = t1 - borrow;
        d[{{i}}] = v;
        borrow = select(0u, 1u, s[{{i}}] < P8_{{i}}) + select(0u, 1u, t1 < borrow);
    }
{{/f8_words}}
    var out: array<u32, 8>;
{{#f8_words}}
    out[{{i}}] = select(d[{{i}}], s[{{i}}], borrow != 0u);
{{/f8_words}}
    return out;
}

fn fr_sub_f8(a: array<u32, 8>, b: array<u32, 8>) -> array<u32, 8> {
    var d: array<u32, 8>;
    var borrow: u32 = 0u;
{{#f8_words}}
    {
        let t1: u32 = a[{{i}}] - b[{{i}}];
        let v: u32 = t1 - borrow;
        d[{{i}}] = v;
        borrow = select(0u, 1u, a[{{i}}] < b[{{i}}]) + select(0u, 1u, t1 < borrow);
    }
{{/f8_words}}
    // d = a - b; on borrow (a < b) the canonical result is d + p, with the
    // 2^256 wrap discarded (a - b + p lands in (0, p)).
    var out: array<u32, 8>;
    var carry: u32 = 0u;
{{#f8_words}}
    {
        let pw: u32 = select(0u, P8_{{i}}, borrow != 0u);
        let lo: u32 = d[{{i}}] + pw;
        let v: u32 = lo + carry;
        out[{{i}}] = v;
        carry = select(0u, 1u, lo < d[{{i}}]) + select(0u, 1u, v < lo);
    }
{{/f8_words}}
    return out;
}
{{/addsub_unpack}}
`;

export const fr_pow = `// Field exponentiation and inversion.
//
// Inputs/outputs are in Montgomery form. The Montgomery representative
// of 1 is R itself (since x*R mod p stores the integer x; 1*R = R), so
// \`get_r()\` is the multiplicative identity here.
//
// \`fr_inv\` is the hot fr operation in the batch-affine pipeline — it's
// the single sequential dependency at the centre of every batch_inverse
// dispatch (one call on tid=0 per workgroup, with the other 63 threads
// blocked at workgroupBarrier waiting). For BN254 with the previous
// Fermat / square-and-multiply implementation this was ~514 montgomery
// products per call, dominating mid-to-late round costs once N drops
// below ~1K. The binary extended GCD path below replaces it with ~256
// outer iterations of cheap BigInt shift / add / sub, plus ONE final
// montgomery_product to convert the native-form result back into
// Montgomery form. About 5-8× faster on the serial path.

// Generic Montgomery-form exponentiation, kept as a fallback / utility.
// Square-and-multiply over the limb-level bits of \`exp\`. Used by tests
// (the fr_pow / fr_inv Jest transcription) but no longer the primary
// fr_inv backbone.
fn fr_pow(base: BigInt, exp: BigInt) -> BigInt {
    var result: BigInt = get_r();   // Montgomery 1
    var b: BigInt = base;

    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        for (var j = 0u; j < WORD_SIZE; j = j + 1u) {
            if (((exp.limbs[i] >> j) & 1u) == 1u) {
                result = montgomery_product(&result, &b);
            }
            b = montgomery_product(&b, &b);
        }
    }
    return result;
}

// (p - 2) as a plain (non-Montgomery) BigInt. Used by fr_pow_inv as the
// exponent in Fermat's little theorem: a^(p-2) ≡ a^(-1) (mod p).
fn get_p_minus_2() -> BigInt {
    var e: BigInt;
{{{ p_minus_2_limbs }}}
    return e;
}

// Field inversion via Fermat's little theorem: a^(-1) ≡ a^(p-2) (mod p).
// Both input and output are in Montgomery form. Since \`fr_pow\` preserves
// Montgomery form (Mont(base)^exp -> Mont(base^exp)), the result of
// \`fr_pow(Mont(a), p-2)\` is directly Mont(a^(-1)). No extra correction.
//
// Cost: ~254 squarings + ~127 expected multiplies (half the bits of p-2
// are set), ≈ 381 montgomery_products per call. Compare to fr_inv's
// jumpy K=12 safegcd which converges in ~62 outer iters with ~10
// BigInt-ops each plus ONE montgomery_product at the end.
fn fr_pow_inv(a: BigInt) -> BigInt {
    var exp: BigInt = get_p_minus_2();
    return fr_pow(a, exp);
}

// R^3 mod p. Used by \`fr_inv\` to convert the binary-GCD output (which is
// in native form, pre-multiplied by R^(-1) because the input was in
// Montgomery form) back into Montgomery form via a single
// montgomery_product. See the derivation in the fr_inv body.
fn get_r_cubed() -> BigInt {
    var r3: BigInt;
{{{ r_cubed_limbs }}}
    return r3;
}

// Field inversion via Pornin's jumpy safegcd (Bernstein-Yang with K-step
// inner divsteps). https://eprint.iacr.org/2020/972
//
// Input \`a\` is in Montgomery form (encoding integer A = a · R mod p).
// Output is Montgomery form mont(a^(-1)) = a^(-1) · R mod p.
//
// === Algorithm overview ===
//
// State: (f, g, u, v, delta) where
//   - f, g: 2's complement signed BigInts on NUM_WORDS·WORD_SIZE = 260
//     bits. f starts as p, g as A. Bernstein-Yang invariant guarantees
//     |f|, |g| ≤ p < 2^254 throughout (6 spare bits including sign).
//   - u, v: in [0, p), canonical. Track M[0][1] mod p and M[1][1] mod p
//     of the cumulative transformation matrix.
//   - delta: signed i32 driving the step choice.
//
// Each OUTER iteration:
//   1. Extract the low WORD_SIZE bits of f, g into i32 approximations
//      (f_inner, g_inner). Run K=12 INNER divsteps on these — cheap
//      i32 operations — while accumulating an unscaled integer matrix
//      [[u00, u01], [u10, u11]] with entries bounded by 2^K. The
//      divstep CHOICES only depend on (delta, g & 1), and the low K+1
//      bits of g preserve g's low-bit evolution through K steps, so
//      the matrix from the inner loop equals what plain safegcd would
//      have built over K steps.
//
//   2. Apply the matrix to full (f, g) via signed multi-limb mul + arith
//      shift right by K (\`bigint_signed_axby_shr_k\`):
//        new_f = (u00 · f + u01 · g) >> K
//        new_g = (u10 · f + u11 · g) >> K
//      Divisibility by 2^K is guaranteed by the algorithm; the shift
//      is exact.
//
//   3. Apply the matrix mod p to (u, v) via the generalized m-trick
//      (\`bigint_signed_axby_modp_halve_k\`):
//        new_u = halve_mod_p((u00 · u + u01 · v), K)
//        new_v = halve_mod_p((u10 · u + u11 · v), K)
//
// === Iteration count ===
//
// Pornin's Theorem 11.2 bound: ⌈(49n + 80) / (17 · K)⌉ outer iterations
// suffice for n-bit inputs. For BN254 (n=254), K=12: ⌈61.4⌉ = 62. Cap
// at 70 for safety.
//
// === Why K=12 ===
//
//   - The approximation needs K+1 = 13 bits of low-bit fidelity, which
//     is exactly one WORD_SIZE limb (limbs[0]).
//   - Matrix entries bounded by 2^K = 4096 fit in i16, with i32 used
//     for arithmetic headroom (subtractions can briefly hit 2^(K+1)).
//   - Per-limb products in the matrix application: limb (2^13) ·
//     matrix_entry (2^12) = 2^25; sum of 2 + carry ≤ 2^27, fits in i32.
//   - \`bigint_halve_k_mod_p\`'s K < WORD_SIZE precondition is satisfied.
//
// === Comparison to plain safegcd (the previous fr_inv) ===
//
// Plain safegcd: ~737 outer iter × ~4 BigInt-equivalent ops/iter.
// Jumpy K=12:    ~62 outer iter × ~10 BigInt-equivalent ops/iter
//                                  (4 muls + accumulate + shift + mod-p
//                                  normalisation), plus ~120 cheap i32
//                                  ops for the inner loop.
//
// Estimated speedup on the critical path: ~2-3× vs plain safegcd in
// total BigInt-op count, depending on how the GPU pipelines the inner
// loop and the multi-limb axby calls.
//
// The previous plain safegcd is kept available as \`fr_inv_plain\` for
// A/B comparison; the previous binary-GCD-with-T1.b/c is \`fr_inv_bgcd\`.
fn fr_inv(a: BigInt) -> BigInt {
    const JUMPY_K: u32 = 12u;
    const JUMPY_MAX_OUTER: u32 = 70u;

    var f: BigInt = get_p();
    var g: BigInt = a;
    var u: BigInt;             // 0 (default-init)
    var v: BigInt;
    v.limbs[0] = 1u;           // 1
    var delta: i32 = 1;

    var p_const: BigInt = get_p();

    var found = false;
    for (var outer_iter: u32 = 0u; outer_iter < JUMPY_MAX_OUTER; outer_iter = outer_iter + 1u) {
        if (bigint_is_zero(&g)) {
            found = true;
            break;
        }

        // Inner loop: K divsteps on (f.limbs[0], g.limbs[0]) treated as
        // i32 approximations. Builds the unscaled 2x2 matrix.
        var u00: i32 = 1i; var u01: i32 = 0i;
        var u10: i32 = 0i; var u11: i32 = 1i;
        var f_inner: i32 = i32(f.limbs[0]);
        var g_inner: i32 = i32(g.limbs[0]);
        var inner_delta: i32 = delta;
        for (var i: u32 = 0u; i < JUMPY_K; i = i + 1u) {
            let g_low: i32 = g_inner & 1i;
            let take_swap: bool = (inner_delta > 0i) && (g_low == 1i);
            if (take_swap) {
                // M_step_unscaled = [[0, 2], [-1, 1]]
                let new_u00: i32 = u10 * 2i;
                let new_u01: i32 = u11 * 2i;
                let new_u10: i32 = u10 - u00;
                let new_u11: i32 = u11 - u01;
                u00 = new_u00; u01 = new_u01;
                u10 = new_u10; u11 = new_u11;

                let new_f: i32 = g_inner;
                g_inner = g_inner - f_inner;
                f_inner = new_f;
                inner_delta = 1i - inner_delta;
            } else if (g_low == 1i) {
                // M_step_unscaled = [[2, 0], [1, 1]]; top row doubles,
                // bottom row gets +(top row).
                u10 = u00 + u10;
                u11 = u01 + u11;
                u00 = u00 * 2i;
                u01 = u01 * 2i;
                g_inner = g_inner + f_inner;
                inner_delta = inner_delta + 1i;
            } else {
                // M_step_unscaled = [[2, 0], [0, 1]]; only top row doubles.
                u00 = u00 * 2i;
                u01 = u01 * 2i;
                inner_delta = inner_delta + 1i;
            }
            // Halve g_inner (arith shr 1).
            g_inner = g_inner >> 1u;
        }
        delta = inner_delta;

        // Apply matrix to (f, g): full multi-limb signed mul + arith shr K.
        var new_f: BigInt;
        var new_g: BigInt;
        bigint_signed_axby_shr_k(&f, u00, &g, u01, JUMPY_K, &new_f);
        bigint_signed_axby_shr_k(&f, u10, &g, u11, JUMPY_K, &new_g);
        f = new_f;
        g = new_g;

        // Apply matrix mod p to (u, v): m-trick generalized for ax + by.
        var new_u: BigInt;
        var new_v: BigInt;
        bigint_signed_axby_modp_halve_k(&u, u00, &v, u01, &p_const, JUMPY_K, &new_u);
        bigint_signed_axby_modp_halve_k(&u, u10, &v, u11, &p_const, JUMPY_K, &new_v);
        u = new_u;
        v = new_v;
    }

    // Defensive: if \`a\` was 0 (or didn't converge), return 0.
    if (!found) {
        var zero: BigInt;
        return zero;
    }

    // a^(-1) ≡ sign(f) · u (mod p). If f is negative, negate u mod p.
    var inv_native: BigInt = u;
    if (bigint_is_neg_2c(&f)) {
        var negated: BigInt;
        let _b = bigint_sub(&p_const, &u, &negated);
        inv_native = negated;
    }

    // Convert native → Montgomery: mont_product(inv_native, R^3).
    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}

// Plain safegcd (1 divstep per iteration). Kept for A/B comparison
// against the jumpy \`fr_inv\` above. Not called by production.
fn fr_inv_plain(a: BigInt) -> BigInt {
    var f: BigInt = get_p();
    var g: BigInt = a;
    var v: BigInt;             // 0 (default-init)
    var r: BigInt;
    r.limbs[0] = 1u;           // 1
    var delta: i32 = 1;

    var p_const: BigInt = get_p();

    var found = false;
    for (var iter: u32 = 0u; iter < 750u; iter = iter + 1u) {
        if (bigint_is_zero(&g)) {
            found = true;
            break;
        }

        let g_low: u32 = g.limbs[0] & 1u;
        let take_swap: bool = (delta > 0) && (g_low == 1u);

        if (take_swap) {
            var diff: BigInt;
            bigint_sub_2c(&g, &f, &diff);
            bigint_arith_shr1(&diff);
            var saved_g: BigInt = g;
            f = saved_g;
            g = diff;
            delta = 1 - delta;

            var rv_diff: BigInt = fr_sub(&r, &v);
            bigint_halve_k_mod_p(&rv_diff, &p_const, 1u);
            v = r;
            r = rv_diff;
        } else if (g_low == 1u) {
            var sum: BigInt;
            bigint_add_2c(&g, &f, &sum);
            bigint_arith_shr1(&sum);
            g = sum;
            delta = delta + 1;

            var rv_sum: BigInt = fr_add(&r, &v);
            bigint_halve_k_mod_p(&rv_sum, &p_const, 1u);
            r = rv_sum;
        } else {
            bigint_arith_shr1(&g);
            delta = delta + 1;
            bigint_halve_k_mod_p(&r, &p_const, 1u);
        }
    }

    if (!found) {
        var zero: BigInt;
        return zero;
    }

    var inv_native: BigInt = v;
    if (bigint_is_neg_2c(&f)) {
        var negated: BigInt;
        let _b = bigint_sub(&p_const, &v, &negated);
        inv_native = negated;
    }

    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}

// Legacy binary-extended-GCD fr_inv. Kept available for A/B comparison
// against the safegcd path above. Not called by the production kernel
// — the dispatcher picks \`fr_inv\` (safegcd). To swap back, rename
// \`fr_inv_bgcd\` here to \`fr_inv\` and rename the safegcd version above
// to something else.
//
// Two perf optimisations on top of the textbook formulation:
//
//   * CTZ-bulk halving (T1.b). The textbook "while u even: shr1" inner
//     loop iterates one bit at a time; instead we read the trailing-zero
//     count of u's low limb and shift by that many bits in one limb-pass.
//     For x1 we use the m-trick \`bigint_halve_k_mod_p\`: the unique
//     m ∈ [0, 2^k) with (x1 + m·p) ≡ 0 (mod 2^k) lets us perform k
//     halvings as one BigInt-add and one shr-by-k. Average ~2× speedup
//     on the inner halving block (random binary GCD has E[ctz] ≈ 2).
//
//   * Limb-bound tracking (T1.c). We keep \`top_u\`, \`top_v\` as loose
//     upper bounds on the highest non-zero limb of u and v. Both shrink
//     monotonically as the algorithm progresses; using the bounded
//     \`_top\` variants of shr1 / is_one / gte / sub halves the per-op
//     cost on average across the ~250 outer iterations it takes for
//     254-bit inputs to converge.
fn fr_inv_bgcd(a: BigInt) -> BigInt {
    var u: BigInt = a;
    var v: BigInt = get_p();

    var x1: BigInt;             // x1 = 1
    x1.limbs[0] = 1u;
    var x2: BigInt;             // x2 = 0  (default-initialized)

    var p_const: BigInt = get_p();

    // Loose upper bounds on the topmost non-zero limb of u and v. p
    // uses limb (NUM_WORDS - 1) (BN254: bit 254 fits in limb 19), and
    // a < p so u also fits there at start. Both shrink monotonically;
    // we tighten with \`bigint_recompute_top\` after every shift /
    // subtraction. x1 / x2 stay in [0, p) throughout, so they don't
    // benefit from limb-bound tracking.
    var top_u: u32 = NUM_WORDS - 1u;
    var top_v: u32 = NUM_WORDS - 1u;

    var inv_native: BigInt;
    var found = false;
    for (var iter: u32 = 0u; iter < 1024u; iter = iter + 1u) {
        if (bigint_is_one_top(&u, top_u)) {
            inv_native = x1;
            found = true;
            break;
        }
        if (bigint_is_one_top(&v, top_v)) {
            inv_native = x2;
            found = true;
            break;
        }

        // Halve u while it's even, applying matched halvings to x1 mod p
        // so the invariant A * x1 ≡ u (mod p) is maintained. The
        // \`bigint_ctz_lo_capped\` returns 1..WORD_SIZE-1 trailing zeros
        // of the low limb; if the low limb itself is zero (we've cleared
        // a full word of trailing zeros) it returns WORD_SIZE-1, so the
        // bulk shift always makes progress and we re-enter the loop to
        // strip more.
        loop {
            if (!bigint_is_even(&u)) { break; }
            let k = bigint_ctz_lo_capped(&u);
            bigint_shr_k_in_word_top(&u, k, top_u);
            top_u = bigint_recompute_top(&u, top_u);
            bigint_halve_k_mod_p(&x1, &p_const, k);
        }

        // Same for v / x2.
        loop {
            if (!bigint_is_even(&v)) { break; }
            let k = bigint_ctz_lo_capped(&v);
            bigint_shr_k_in_word_top(&v, k, top_v);
            top_v = bigint_recompute_top(&v, top_v);
            bigint_halve_k_mod_p(&x2, &p_const, k);
        }

        // Both u and v are now odd. Subtract the smaller from the
        // larger; mirror the subtraction on the x1/x2 coefficients
        // mod p (fr_sub returns canonical [0, p)). The cost-bounding
        // top is the larger of the two — at most one of u, v can be
        // > the other so iterating up to max(top_u, top_v) is tight.
        let top_uv: u32 = max(top_u, top_v);
        if (bigint_gte_top(&u, &v, top_uv)) {
            bigint_sub_top_inplace(&u, &v, top_uv);
            top_u = bigint_recompute_top(&u, top_u);
            x1 = fr_sub(&x1, &x2);
        } else {
            bigint_sub_top_inplace(&v, &u, top_uv);
            top_v = bigint_recompute_top(&v, top_v);
            x2 = fr_sub(&x2, &x1);
        }
    }

    // Defensive: if \`a\` was 0 the algorithm would not converge — return
    // 0 in that case (and any caller passing a zero delta is already
    // buggy upstream; the schedule kernel filters delta == 0).
    if (!found) {
        var zero: BigInt;
        return zero;
    }

    // inv_native = a^(-1) * R^(-1) mod p (in [0, p)).
    // Multiply by R^3 in Montgomery domain to land back in Montgomery
    // form: see derivation in the function header.
    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}
`;

export const mont_pro_product_f32_22_sos3uv3 = `// 22-bit-limb f32 Montgomery product, sos3uv3 — chain breaking via
// SEPARATE per-slot f32 accumulators (lo and hi).
//
// Inside the inner-j loop:
//   - sos3uv2 had a single chain c_hi/c_lo flowing j → j+1 (serial).
//   - sos3u32 used i32 accumulators (broken chain but slow int ops).
//   - sos3uv3 uses TWO per-slot f32 accumulators (tlo[k], thi[k]).
//     Each j writes UNIQUE tlo[j-1] and thi[j] — no overlap across j's,
//     no carry chain. Stays in f32 throughout (no int conversions).
//
// Per-slot bound: tlo[k] = s_old[k+1] + 1 lo (≤ 2.5W). thi[k] = 1 hi
// (≤ W). Combined at drain: 3.5W < 2²³·⁸ < 2²⁴ — fits f32 exactly.
//
// Drain at end of each outer iter: combine tlo[k] + thi[k] + carry,
// floor-based bias_split, write canonical s[k]. Serial across cols.
//
// === Structure ===
// Outer iter i=0 is unrolled (no shifted-in s values to read). Iters
// 1..N-1 are in a runtime \`for\` loop with a separate slot_init that pulls
// in s1..s11. Inner-j pairs and drain cols are mustache-expanded — keeps
// the named locals (tlo0..tlo11, thi0..thi11) which Metal can register-
// allocate instead of spilling to thread-private memory.

const NUM_LIMBS: u32 = {{ num_limbs }}u;
const N0: f32        = {{ n0 }};
const N0_SCALED: f32 = {{ n0_scaled }};
const TWO_W: f32     = 8388608.0;          // 2 * 2^22

fn get_p_f32() -> BigIntF32 {
    var p: BigIntF32;
{{{ p_limbs_f32 }}}
    return p;
}

fn bias_split_f32_le2w(x: f32) -> vec2<f32> {
    let hi = step(W, x);
    let lo = fma(-hi, W, x);
    return vec2<f32>(hi, lo);
}

fn bias_split_f32_le4w(x: f32) -> vec2<f32> {
    let hi = floor(x * W_INV);
    let lo = fma(-hi, W, x);
    return vec2<f32>(hi, lo);
}

fn mulhilo_sos3_corr(a: f32, a_scaled: f32, b: f32) -> vec2<f32> {
    let hi_off_inner = fma(a_scaled, b, W);
    let hi_off       = floor(hi_off_inner);
    let neg_hi_w     = fma(-W, hi_off, BIAS);
    let lo0          = fma(a, b, neg_hi_w);
    let hi_pre       = hi_off - W;
    let underflow    = step(lo0, -0.5);
    let hi           = hi_pre - underflow;
    let lo           = fma(underflow, W, lo0);
    return vec2<f32>(hi, lo);
}

fn mulhilo_sos3_qi_lo(a: f32, b_scaled: f32, b: f32) -> f32 {
    let hi_off_inner = fma(a, b_scaled, W);
    let hi_off       = floor(hi_off_inner);
    let neg_hi_w     = fma(-W, hi_off, BIAS);
    let lo0          = fma(a, b, neg_hi_w);
    let underflow    = step(lo0, -0.5);
    let lo           = fma(underflow, W, lo0);
    return lo;
}

fn mulhilo_sos3_2_v2(a: vec2<f32>, a_scaled: vec2<f32>, b: vec2<f32>) -> vec4<f32> {
    let hi_off_inner = fma(a_scaled, b, vec2<f32>(W, W));
    let hi_off       = floor(hi_off_inner);
    let neg_hi_w     = fma(vec2<f32>(-W, -W), hi_off, vec2<f32>(BIAS, BIAS));
    let lo           = fma(a, b, neg_hi_w);
    return vec4<f32>(hi_off.x, lo.x, hi_off.y, lo.y);
}

fn montgomery_product_f32_unreduced(x: ptr<function, BigIntF32>, y: ptr<function, BigIntF32>) -> BigIntF32 {
    var s0: f32  = 0.0;
    var s1: f32  = 0.0;
    var s2: f32  = 0.0;
    var s3: f32  = 0.0;
    var s4: f32  = 0.0;
    var s5: f32  = 0.0;
    var s6: f32  = 0.0;
    var s7: f32  = 0.0;
    var s8: f32  = 0.0;
    var s9: f32  = 0.0;
    var s10: f32 = 0.0;
    var s11: f32 = 0.0;

    var p = get_p_f32();

    // ===== Outer iter i=0 (unrolled — s[*] all zero, no shift-in). =====
    {
        let x_i        = (*x).limbs[0];
        let x_i_scaled = x_i * W_INV;
        let xy0        = mulhilo_sos3_corr(x_i, x_i_scaled, (*y).limbs[0]);
        let qi         = mulhilo_sos3_qi_lo(xy0.y, N0_SCALED, N0);
        let qi_scaled  = qi * W_INV;

        let c_cancel = step(0.5, xy0.y);
        let qp0_lo   = c_cancel * (W - xy0.y);
        let qp0_hi   = fma(qi, p.limbs[0], -qp0_lo) * W_INV;

        // j=0's contribution to slot 0 (= position 1 unshifted).
        let init_slot0 = xy0.x + qp0_hi + c_cancel;

        // Slot init for iter 0: tlo[0] gets init_slot0; everything else 0.
{{#slot_inits_i0}}
        var {{name}}: f32 = {{init_expr}};
{{/slot_inits_i0}}

        let xq_scaled = vec2<f32>(x_i_scaled, qi_scaled);
        let xq        = vec2<f32>(x_i, qi);

        // Inner-j writes: pair (y[j], p[j]) mulhilo, lo to tlo[j-1], hi to thi[j].
{{#inner_pairs}}
        {
            let mh = mulhilo_sos3_2_v2(xq, xq_scaled, vec2<f32>((*y).limbs[{{j}}u], p.limbs[{{j}}u]));
            let lo_sum = mh.y + mh.w;
            let hi_sum = mh.x + mh.z - TWO_W;
            tlo{{km1}} = tlo{{km1}} + lo_sum;
            thi{{k}}   = thi{{k}}   + hi_sum;
        }
{{/inner_pairs}}

        // Drain: combine tlo[k]+thi[k]+carry, split. Serial across cols.
        var carry: f32 = 0.0;
{{#drain_cols}}
        {
            let sum = tlo{{k}} + thi{{k}} + carry;
            let split = bias_split_f32_le4w(sum);
            s{{k}} = split.y;
            carry = split.x;
        }
{{/drain_cols}}
    }

    // ===== Outer iter i=1..NUM_LIMBS-1 (runtime loop). =====
    for (var i = 1u; i < NUM_LIMBS; i = i + 1u) {
        let x_i        = (*x).limbs[i];
        let x_i_scaled = x_i * W_INV;

        let xy0       = mulhilo_sos3_corr(x_i, x_i_scaled, (*y).limbs[0]);
        let sum0      = s0 + xy0.y;
        let sum0_s    = bias_split_f32_le2w(sum0);
        let qi        = mulhilo_sos3_qi_lo(sum0_s.y, N0_SCALED, N0);
        let qi_scaled = qi * W_INV;

        let c_cancel = step(0.5, sum0_s.y);
        let qp0_lo   = c_cancel * (W - sum0_s.y);
        let qp0_hi   = fma(qi, p.limbs[0], -qp0_lo) * W_INV;

        // j=0's contribution to slot 0 + s_old[1] shifted in.
        let init_slot0 = xy0.x + qp0_hi + c_cancel + sum0_s.x;

        // Slot init for i>=1: tlo[k] pulls in s[k+1] as the shifted carry.
{{#slot_inits_general}}
        var {{name}}: f32 = {{init_expr}};
{{/slot_inits_general}}

        let xq_scaled = vec2<f32>(x_i_scaled, qi_scaled);
        let xq        = vec2<f32>(x_i, qi);

{{#inner_pairs}}
        {
            let mh = mulhilo_sos3_2_v2(xq, xq_scaled, vec2<f32>((*y).limbs[{{j}}u], p.limbs[{{j}}u]));
            let lo_sum = mh.y + mh.w;
            let hi_sum = mh.x + mh.z - TWO_W;
            tlo{{km1}} = tlo{{km1}} + lo_sum;
            thi{{k}}   = thi{{k}}   + hi_sum;
        }
{{/inner_pairs}}

        var carry: f32 = 0.0;
{{#drain_cols}}
        {
            let sum = tlo{{k}} + thi{{k}} + carry;
            let split = bias_split_f32_le4w(sum);
            s{{k}} = split.y;
            carry = split.x;
        }
{{/drain_cols}}
    }

    var s: BigIntF32;
    s.limbs[0]  = s0;
    s.limbs[1]  = s1;
    s.limbs[2]  = s2;
    s.limbs[3]  = s3;
    s.limbs[4]  = s4;
    s.limbs[5]  = s5;
    s.limbs[6]  = s6;
    s.limbs[7]  = s7;
    s.limbs[8]  = s8;
    s.limbs[9]  = s9;
    s.limbs[10] = s10;
    s.limbs[11] = s11;
    return s;
}

fn montgomery_product_f32(x: ptr<function, BigIntF32>, y: ptr<function, BigIntF32>) -> BigIntF32 {
    var s = montgomery_product_f32_unreduced(x, y);
    var p = get_p_f32();
    return conditional_reduce_f32(&s, &p);
}

fn conditional_reduce_f32(x: ptr<function, BigIntF32>, y: ptr<function, BigIntF32>) -> BigIntF32 {
    if (bigint_f32_gt(x, y) || bigint_f32_eq(x, y)) {
        var res: BigIntF32;
        let _borrow = bigint_f32_sub(x, y, &res);
        return res;
    }
    return *x;
}
`;

export const mont_pro_product_karat_yuval = `// u32 Montgomery product via recursive KARATSUBA + YUVAL reduction.
// Fully unrolled — all indices compile-time constants so WGSL→MSL can
// SROA the temp slots into registers instead of thread-local memory.
//
// === Register-light grouped emit ===
// The multiply is emitted grouped by half-product: each of P_lo, P_hi,
// P_cr gets one scoped block that computes its 3 schoolbook sub-products
// and folds the Karatsuba-combined result straight into the 40-limb
// accumulator t. Only one group's 27 schoolbook outputs are live at a
// time (not all 81) — identical arithmetic, same 225 multiplies, same
// combine adds; just a tighter live-range schedule that roughly halves
// the register peak, keeping small-register-file GPUs off the spill cliff.
//
// === Layout ===
// 4 input chunks per operand (5 limbs each, named locals):
//   x_lo_lo = x[0..4],  x_lo_hi = x[5..9]
//   x_hi_lo = x[10..14], x_hi_hi = x[15..19]
//   (same naming for y)
//
// 9 sub-sub-products (each 5×5 schoolbook → 9 output limbs):
//   For P_lo  = x[0..9]·y[0..9]:    pp_lo_LL, pp_lo_HH, pp_lo_C
//   For P_hi  = x[10..19]·y[10..19]: pp_hi_LL, pp_hi_HH, pp_hi_C
//   For P_cr  = (x[0..9]+x[10..19])·(y[0..9]+y[10..19]):
//                                    pp_cr_LL, pp_cr_HH, pp_cr_C
//
// 3 outer sub-products (inner Karat combine):
//   P_lo[k]  = pp_lo_LL[k]  + (pp_lo_C[k-5] - pp_lo_LL[k-5] - pp_lo_HH[k-5]) + pp_lo_HH[k-10]
//   P_hi[k]  = pp_hi_LL[k]  + (pp_hi_C[k-5] - pp_hi_LL[k-5] - pp_hi_HH[k-5]) + pp_hi_HH[k-10]
//   P_cr[k]  = pp_cr_LL[k]  + (pp_cr_C[k-5] - pp_cr_LL[k-5] - pp_cr_HH[k-5]) + pp_cr_HH[k-10]
//
// Outer combine into temp[0..38]:
//   temp[k]      += P_lo[k]                                   for k in [0, 18]
//   temp[k+20]   += P_hi[k]                                   for k in [0, 18]
//   temp[k+10]   += P_cr[k] - P_lo[k] - P_hi[k]               for k in [0, 18]
//
// Yuval reduce (N-1 calls + 1 standard):
//   for i in 0..N-1:
//     t_mask = temp[i] & MASK; carry = temp[i] >> WORD_SIZE
//     temp[i+1] += t_mask·R_INV[0] + carry
//     temp[i+1+j] += t_mask·R_INV[j]                          for j in [1, N)
//   standard reduce at i=N-1: k = (temp[i]&MASK)·N0 & MASK;
//     temp[i+j] += k·p[j]                                     for j in [0, N)
//     plus the (temp[i]>>WORD_SIZE) carry folded into temp[i+1]
//
// Final canonicalization: single carry pass over the upper N slots.
//
// === Why no drains in the multiply phase ===
// One inner sub-product (pp_cr_C slot 4 = 80·W² = 2³²·³²) wraps u32 by
// ~1.25×. This wrap is HARMLESS: the subsequent \`pp_cr_C - pp_cr_LL -
// pp_cr_HH\` subtraction unwinds the wrap via modular arithmetic, giving
// the correct (mathematically non-negative) pp_cr_mid value, which fits
// u32. Every other intermediate fits u32 directly. See
// karat_intermediate_check.mjs for the per-slot proof.
//
// Final temp[k] math bound: 40·W² = 2³¹·³² < 2³². ✓ Zero drains needed.

const NUM_WORDS: u32 = {{ num_words }}u;
const WORD_SIZE: u32 = {{ word_size }}u;
const MASK: u32      = {{ mask }}u;
const TWO_POW_WORD_SIZE: u32 = {{ two_pow_word_size }}u;
const N0: u32        = {{ n0 }}u;
const P_INV_MOD_2W: u32 = {{ p_inv_mod_2w }}u;

// r_inv = 2^{-WORD_SIZE} mod p, as N individual constants (NOT array —
// naga rejects runtime indexing into a const array, and the unrolled
// Yuval below uses each limb at a compile-time position anyway).
{{#r_inv_consts}}
const R_INV_{{idx}}: u32 = {{val}}u;
{{/r_inv_consts}}

// The modulus limbs, in the same individual-const form. montgomery_product
// reads these only at compile-time-constant positions (the fully-unrolled
// standard Montgomery reduce), so the compiler folds them to immediates
// instead of holding p as a 20-register value live across the whole
// multiply. get_p() below still materialises p for the rare caller that
// needs an addressable BigInt (conditional_reduce, the field ops).
{{#p_limbs_consts}}
const P_LIMB_{{idx}}: u32 = {{val}}u;
{{/p_limbs_consts}}

fn get_p() -> BigInt {
    var p: BigInt;
{{{ p_limbs }}}
    return p;
}

fn montgomery_product(x_ptr: ptr<function, BigInt>, y_ptr: ptr<function, BigInt>) -> BigInt {
    // === Grouped Karatsuba multiply + combine (generated). ===
    // Per half-product (lo / hi / cr) a scoped block computes 3 schoolbook
    // 5×5 sub-products and folds the Karatsuba-combined result straight
    // into the 40-limb accumulator t0..t39. See renderKaratYuvalMont.
{{{ multiply_body }}}

    // === Yuval reduce: 19 Yuval calls + 1 standard. ===
    // Each call extracts t_mask & carry from t{i}, then accumulates
    // t_mask·R_INV[j] into t{i+1+j} for j=0..N-1 (the carry folds into
    // the j=0 write).
{{#yuval_iters}}
    {
        let t_mask: u32 = t{{i}} & MASK;
        let carry: u32  = t{{i}} >> WORD_SIZE;
{{#writes}}
        t{{slot}} = t{{slot}} + t_mask * R_INV_{{r_idx}}{{#first}} + carry{{/first}};
{{/writes}}
    }
{{/yuval_iters}}

    // Standard Mont reduce for the last iter (i = N-1 = 19).
    {
        let t_mask: u32 = t{{i_std}} & MASK;
        let k_std: u32  = (t_mask * N0) & MASK;
{{#standard_writes}}
        t{{slot}} = t{{slot}} + k_std * P_LIMB_{{p_idx}}{{#first}} + (t{{i_std}} >> WORD_SIZE){{/first}};
{{/standard_writes}}
    }

    // === Final canonicalization (single carry pass over t20..t39). ===
    var c: u32 = 0u;
{{#final_drain}}
    {
        let v: u32 = t{{slot}} + c;
        c = v >> WORD_SIZE;
        t{{slot}} = v & MASK;
    }
{{/final_drain}}

    // === Repack canonical limbs into BigInt and return. ===
    var s: BigInt;
{{#extract}}
    s.limbs[{{out_k}}u] = t{{src_slot}};
{{/extract}}

    return conditional_reduce(&s);
}

// conditional_reduce runs after the unrolled multiply/reduce, when only \`s\`
// is still live — its local \`var p\` does not overlap the multiply's
// register peak, so materialising p here is free.
fn conditional_reduce(x: ptr<function, BigInt>) -> BigInt {
    var p = get_p();
    var x_gt_y = bigint_gt(x, &p);
    var x_eq_y = bigint_eq(x, &p);
    if (x_gt_y == 1u || x_eq_y) {
        var res: BigInt;
        bigint_sub(x, &p, &res);
        return res;
    }
    return *x;
}
`;

export const mulhilo_22 = `// 22-bit-limb sibling of \`mulhilo.wgsl\`. Same FMA-bias trick, different
// constants (W = 2^22, BIAS = 2^44). The two files are never compiled
// into the same WGSL module — callers pick one bundle or the other.
//
// Inputs:  a, b in [0, 2^22) stored as f32 (integer-valued).
// Output:  vec2(hi, lo) with a*b == hi * 2^22 + lo,  hi, lo in [0, 2^22).
//
// Math (load-bearing):
//   fma(a, b, BIAS) computes a*b + 2^44 with infinite intermediate
//   precision and rounds ONCE to f32. Inside [2^44, 2^45) the f32 ULP is
//   exactly 2^21, so the rounded result lies on a multiple of 2^21
//   (not 2^22!). Dividing by W and flooring effectively rounds to W,
//   giving a non-negative integer q/W < W. The lo correction follows the
//   same step()-based underflow scheme as the 23-bit variant.
//
// Important difference from 23-bit: at 22-bit, a*b in [0, 2^44) plus
// BIAS = 2^44 sits exactly at the boundary [2^44, 2^45]. Inside that
// range ULP is 2^21, so \`floor(abp * W_INV)\` rounds to the nearest
// multiple of W/2 — but then \`lo0 = fma(a, b, -hi_pre * W)\` recovers
// exactly. The step() correction handles the half-W slop.
const BIAS: f32 = 17592186044416.0;            // 2^44
const W: f32    = 4194304.0;                   // 2^22
const W_INV: f32 = 2.384185791015625e-7;       // 2^-22

fn mulhilo(a: f32, b: f32) -> vec2<f32> {
    let abp = fma(a, b, BIAS);
    let hi_pre = floor(abp * W_INV) - W;
    let lo0 = fma(a, b, -hi_pre * W);
    let underflow = step(lo0, -0.5);
    let hi = hi_pre - underflow;
    let lo = lo0 + underflow * W;
    return vec2<f32>(hi, lo);
}

fn mulhilo2(a: vec2<f32>, b: vec2<f32>) -> vec4<f32> {
    let abp = fma(a, b, vec2<f32>(BIAS, BIAS));
    let hi_pre = floor(abp * W_INV) - vec2<f32>(W, W);
    let lo0 = fma(a, b, -hi_pre * W);
    let underflow = step(lo0, vec2<f32>(-0.5, -0.5));
    let hi = hi_pre - underflow;
    let lo = lo0 + underflow * W;
    return vec4<f32>(hi.x, lo.x, hi.y, lo.y);
}
`;

export const structs = `struct Point {
  x: BigInt,
  y: BigInt,
  z: BigInt
}

struct BigInt {
    limbs: array<u32, {{ num_words }}>
}
`;
